def _activity_context_from_list(activities, now=None, source="Intervals.icu", context_date=None):
    """Build training context for a specific local date.

    For a backfilled date we intentionally avoid pretending to know the exact
    PRE/POST phase at which the athlete felt that way. Instead we report the
    completed full-day activity context for that date.
    """
    now = now or get_rome_now()
    today_iso = now.date().isoformat()
    context_date = _safe_iso_date(context_date, today_iso)
    day_acts = [a for a in (activities or []) if str(a.get("start_date_local") or "")[:10] == context_date]
    parsed = []
    for a in day_acts:
        dt = parse_local_activity_datetime(a.get("start_date_local"))
        parsed.append((a, dt))
    am_done = any(dt is not None and dt.hour < 12 for _, dt in parsed)
    pm_done = any(dt is not None and dt.hour >= 17 for _, dt in parsed)
    day_load = sum(float(a.get("icu_training_load") or 0) for a, _ in parsed if isinstance(a.get("icu_training_load"), (int, float)))

    if context_date < today_iso:
        phase = "RETRO · FULL DAY"
    elif now.hour < 12:
        phase = "POST-AM" if am_done else "PRE-AM"
    elif now.hour < 17:
        phase = "POST-AM" if am_done else "MIDDAY"
    else:
        phase = "POST-PM" if pm_done else "PRE-PM"

    return {
        "phase": phase,
        "session_count": len(day_acts),
        "today_load": round(day_load, 1),
        "am_done": am_done,
        "pm_done": pm_done,
        "context_source": source,
        "context_date": context_date,
    }


def fetch_activity_context_for_date(context_date=None, now=None):
    """Lightweight Intervals refresh for the selected check-in date. Never calls Claude."""
    now = now or get_rome_now()
    today_iso = now.date().isoformat()
    target = _safe_iso_date(context_date, today_iso)
    if target > today_iso:
        raise ValueError("Daily Log cannot be dated in the future")
    retrospective = target < today_iso
    suffix = " · retrospective" if retrospective else ""
    if not ICU_API_KEY or not ICU_ATHLETE_ID:
        return _activity_context_from_list([], now=now, source="Clock only" + suffix, context_date=target)
    fields = "id,name,type,start_date_local,moving_time,elapsed_time,icu_training_load"
    url = (
        f"https://intervals.icu/api/v1/athlete/{ICU_ATHLETE_ID}/activities"
        f"?oldest={target}&newest={target}&fields={fields}"
    )
    try:
        response = requests.get(url, headers=get_intervals_headers(), timeout=12)
        response.raise_for_status()
        return _activity_context_from_list(response.json(), now=now, source="Intervals.icu" + suffix, context_date=target)
    except Exception:
        return _activity_context_from_list([], now=now, source="Clock only · Intervals unavailable" + suffix, context_date=target)


def fetch_today_activity_context(now=None):
    """Compatibility wrapper for today's check-in context. Never calls Claude."""
    now = now or get_rome_now()
    return fetch_activity_context_for_date(now.date().isoformat(), now=now)


def save_daily_log(feeling, note="", status="NORMAL", restriction_type="NONE", duration_days=None, until_date=None, activity_context=None, log_date=None):
    now = get_rome_now()
    today_iso = now.date().isoformat()
    log_date = _safe_iso_date(log_date, today_iso)
    if log_date > today_iso:
        raise ValueError("Daily Log cannot be dated in the future")
    feeling = int(feeling)
    if not 1 <= feeling <= 10:
        raise ValueError("Feeling must be between 1 and 10")
    status = (status or "NORMAL").strip().upper()
    if status not in ("NORMAL", "REST", "SICK", "INJURED", "UNAVAILABLE"):
        status = "NORMAL"
    restriction_type = (restriction_type or "NONE").strip().upper()
    if restriction_type not in ("NONE", "NO_TRAINING", "NO_INTENSITY"):
        restriction_type = "NONE"

    if status in ("SICK", "REST", "UNAVAILABLE") and restriction_type == "NONE":
        restriction_type = "NO_TRAINING"
    if status == "INJURED" and restriction_type == "NONE":
        restriction_type = "NO_INTENSITY"

    end_date = None
    try:
        days = int(duration_days) if duration_days not in (None, "") else None
    except (TypeError, ValueError):
        days = None
    if days and days > 0:
        end_date = (date.fromisoformat(log_date) + timedelta(days=days - 1)).isoformat()
    else:
        end_date = _safe_iso_date(until_date)
    if (status != "NORMAL" or restriction_type != "NONE") and not end_date:
        end_date = log_date
    if end_date and end_date < log_date:
        end_date = log_date

    ctx = activity_context or _activity_context_from_list([], now=now, source="Clock only", context_date=log_date)
    item_id = uuid.uuid4().hex
    _db_execute(
        """INSERT INTO daily_logs
        (id, logged_at_utc, local_date, local_time, feeling, note, status, status_until, restriction_type, restriction_until, phase, session_count, today_load, am_done, pm_done, context_source)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
        (
            item_id, _now_utc_text(), log_date, now.strftime("%H:%M"), feeling, (note or "").strip(), status,
            end_date if status != "NORMAL" else None,
            restriction_type, end_date if restriction_type != "NONE" else None,
            ctx.get("phase"), ctx.get("session_count", 0), ctx.get("today_load", 0),
            1 if ctx.get("am_done") else 0, 1 if ctx.get("pm_done") else 0, ctx.get("context_source", "Clock only"),
        ),
    )

    if status != "NORMAL" or restriction_type != "NONE":
        kind = status if status != "NORMAL" else "RESTRICTION"
        title = {
            "REST": "Planned rest / no training",
            "SICK": "Illness / health hold",
            "INJURED": "Injury restriction",
            "UNAVAILABLE": "Training unavailable",
            "RESTRICTION": "Temporary training restriction",
        }.get(kind, kind.title())
        add_planning_item(
            kind, title, log_date, end_date, restriction_type,
            note=(note or "").strip(), upsert=True,
        )
    return item_id


def load_daily_logs(limit=120):
    rows = _db_execute(
        "SELECT * FROM daily_logs ORDER BY local_date DESC, local_time DESC, logged_at_utc DESC LIMIT ?",
        (int(limit),), fetch=True,
    )
    # Display / analytics use chronological order.
    rows.reverse()
    return rows


def get_daily_log(log_id):
    rows = _db_execute("SELECT * FROM daily_logs WHERE id=? LIMIT 1", ((log_id or "").strip(),), fetch=True)
    return rows[0] if rows else None


def _report_json_default(value):
    """Conservative JSON fallback for the stored report payload."""
    if isinstance(value, (datetime, date)):
        return value.isoformat()
    if isinstance(value, set):
        return sorted(value)
    return str(value)


def save_latest_report(data, now=None):
    """Persist exactly ONE complete report payload, atomically replacing the previous one.

    This never calls Intervals.icu or the AI Coach. The payload contains only the
    already-computed dashboard/report data, not raw API responses or secrets.
    """
    init_memory_db()
    now = now or get_rome_now()
    generated_at_local = now.isoformat(timespec="seconds")
    generated_at_utc = now.astimezone(ZoneInfo("UTC")).isoformat(timespec="seconds")
    report_data = dict(data or {})
    report_data.pop("best_watts_debug", None)
    report_data.pop("report_save_warning", None)
    payload_json = json.dumps(report_data, ensure_ascii=False, separators=(",", ":"), default=_report_json_default)
    conn = _db_connect()
    try:
        cur = conn.cursor()
        cur.execute(_db_sql("DELETE FROM latest_report"))
        cur.execute(
            _db_sql("INSERT INTO latest_report (singleton_id, generated_at_utc, generated_at_local, app_version, payload_json) VALUES (?, ?, ?, ?, ?)"),
            ("latest", generated_at_utc, generated_at_local, APP_VERSION, payload_json),
        )
        conn.commit()
    finally:
        conn.close()
    return {
        "generated_at_utc": generated_at_utc,
        "generated_at_local": generated_at_local,
        "app_version": APP_VERSION,
        "payload_bytes": len(payload_json.encode("utf-8")),
    }


def _format_report_timestamp(value):
    try:
        dt = datetime.fromisoformat(str(value))
        return dt.strftime("%d/%m/%Y · %I:%M %p")
    except Exception:
        return str(value or "—")


def load_latest_report(include_payload=True):
    """Read the singleton latest report from local/PostgreSQL storage only."""
    rows = _db_execute(
        "SELECT singleton_id, generated_at_utc, generated_at_local, app_version, payload_json FROM latest_report WHERE singleton_id=? LIMIT 1",
        ("latest",), fetch=True,
    )
    if not rows:
        return None
    row = rows[0]
    meta = {
        "generated_at_utc": row.get("generated_at_utc"),
        "generated_at_local": row.get("generated_at_local"),
        "generated_at_local_display": _format_report_timestamp(row.get("generated_at_local")),
        "app_version": row.get("app_version") or "THE LAB",
    }
    raw = row.get("payload_json") or "{}"
    meta["payload_bytes"] = len(raw.encode("utf-8"))
    meta["payload_human"] = _human_bytes(meta["payload_bytes"])
    if include_payload:
        try:
            meta["data"] = json.loads(raw)
        except (TypeError, json.JSONDecodeError):
            meta["data"] = None
    return meta


# V27.1: Last Full Report availability is intentionally NOT a session feature.
# The report lives in PostgreSQL/SQLite and the navigation link is always rendered.
# Logging out clears only the Flask login session; it must never hide or delete the stored report.
def get_latest_report_meta():
    report = load_latest_report(include_payload=False)
    if not report:
        return None
    return {k: report.get(k) for k in ("generated_at_utc", "generated_at_local", "generated_at_local_display", "app_version", "payload_bytes", "payload_human")}


def memory_text_exists(text):
    target = (text or "").strip().casefold()
    if not target:
        return False
    return any((row.get("text") or "").strip().casefold() == target for row in load_memory_items(True, 200))


