@app.route("/service-worker.js")
def service_worker():
    script = 'const CACHE = "the-lab-pwa-v35";\nconst SAFE_ASSETS = ["/manifest.webmanifest", "/pwa-icon-192.png", "/pwa-icon-512.png"];\nself.addEventListener("install", event => { event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(SAFE_ASSETS))); self.skipWaiting(); });\nself.addEventListener("activate", event => { event.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k))))); self.clients.claim(); });\nself.addEventListener("fetch", event => {\n  if (event.request.method !== "GET") return;\n  const url = new URL(event.request.url);\n  if (url.origin !== self.location.origin) return;\n  if (SAFE_ASSETS.includes(url.pathname)) { event.respondWith(caches.match(event.request).then(hit => hit || fetch(event.request))); return; }\n  event.respondWith(fetch(event.request));\n});'
    return Response(script, mimetype="application/javascript", headers={"Service-Worker-Allowed": "/", "Cache-Control": "no-cache"})

