def get_intervals_headers():
    credentials = f"API_KEY:{ICU_API_KEY}"
    encoded = base64.b64encode(credentials.encode("utf-8")).decode("utf-8")
    return {"Authorization": f"Basic {encoded}"}


def fetch_power_curve_payload(newest=None, curve="42d"):
    """Fetch one Intervals.icu cycling power curve.

    ``42d`` is the recent-performance curve already used by THE LAB. ``s0`` is
    the current-season curve and is used only for transparent 42-day-vs-season
    comparisons in the power model. Historical VO2 checkpoints keep the default
    42-day curve by simply omitting ``curve``.
    """
    headers = get_intervals_headers()
    curve = str(curve or "42d").strip()
    url = (
        f"https://intervals.icu/api/v1/athlete/{ICU_ATHLETE_ID}/power-curves.json"
        f"?type=Ride&curves={curve}"
    )
    if newest:
        url += f"&newest={newest}"
    resp = requests.get(url, headers=headers, timeout=30)
    resp.raise_for_status()
    return resp.json()


def extract_power_curve_points(payload):
    """The exact shape of this endpoint's response isn't officially documented.
    The real shape turned out to be a curve object with PARALLEL ARRAYS -
    e.g. {"secs": [5, 10, 15, ...], "watts": [900, 850, ...]} - rather than a
    list of {secs, watts} point dicts. Handle that first, and keep the
    point-list shape as a fallback in case a different curve type (e.g. "all")
    is structured differently."""
    array_results = []
    point_list_results = []

    def walk(node):
        if isinstance(node, dict):
            secs = node.get("secs")
            watts = node.get("watts")
            if watts is None:
                watts = node.get("power")
            if (
                isinstance(secs, list) and isinstance(watts, list)
                and len(secs) == len(watts) and len(secs) > 0
                and isinstance(secs[0], (int, float))
            ):
                array_results.append(
                    [{"secs": s, "watts": w} for s, w in zip(secs, watts) if w]
                )
            for v in node.values():
                walk(v)
        elif isinstance(node, list):
            if node and all(isinstance(i, dict) for i in node):
                keys0 = set(node[0].keys())
                if "secs" in keys0 and ("watts" in keys0 or "power" in keys0):
                    if isinstance(node[0].get("secs"), (int, float)):
                        point_list_results.append(node)
            for item in node:
                walk(item)

    walk(payload)
    if array_results:
        return max(array_results, key=len)
    return point_list_results[0] if point_list_results else None


def format_duration_label(secs):
    if secs < 60:
        return f"{secs}s"
    if secs < 3600:
        return f"{secs // 60}min"
    return f"{secs // 3600}h"


def best_watts_for_durations(points, target_secs_list):
    if not points:
        return []
    sorted_points = sorted(points, key=lambda p: p.get("secs", 0))
    results = []
    for target in target_secs_list:
        best = None
        for p in sorted_points:
            if p.get("secs", 0) <= target:
                best = p
            else:
                break
        if best is None:
            best = sorted_points[0]
        watts = best.get("watts") or best.get("power")
        if watts:
            results.append({"label": format_duration_label(target), "watts": round(watts)})

    if results:
        max_watts = max(r["watts"] for r in results)
        for r in results:
            r["pct"] = round(100 * r["watts"] / max_watts) if max_watts else 0
    return results


def get_best_watts():
    try:
        payload = fetch_power_curve_payload()
        points = extract_power_curve_points(payload)
        result = best_watts_for_durations(points, [5, 15, 60, 300, 1200, 3600])
        debug = None
        if not result:
            preview = json.dumps(payload)[:500]
            debug = "Power curve payload preview: {}".format(preview)
        return result, debug
    except requests.HTTPError as e:
        return [], "Power curve request failed: {}".format(e)
    except Exception as e:
        return [], "Power curve error: {}".format(e)



def _power_at_duration(points, target_secs):
    """Return curve power near a requested duration without inventing a peak.

    Intervals curves normally include standard durations directly. If a target is
    absent, use log-time interpolation only when it is bracketed by real curve
    points; otherwise return None.
    """
    usable = []
    for p in points or []:
        try:
            sec = float(p.get("secs"))
            watts = float(p.get("watts") if p.get("watts") is not None else p.get("power"))
        except (TypeError, ValueError):
            continue
        if sec > 0 and watts > 0:
            usable.append((sec, watts))
    usable.sort()
    if not usable:
        return None
    for sec, watts in usable:
        if abs(sec - target_secs) < 0.5:
            return watts
    lower = None
    upper = None
    for sec, watts in usable:
        if sec < target_secs:
            lower = (sec, watts)
        elif sec > target_secs:
            upper = (sec, watts)
            break
    if not lower or not upper:
        return None
    lo_s, lo_w = lower
    hi_s, hi_w = upper
    # Do not bridge a very sparse section of a curve.
    if hi_s / lo_s > 2.5:
        return None
    frac = (math.log(target_secs) - math.log(lo_s)) / (math.log(hi_s) - math.log(lo_s))
    return lo_w + frac * (hi_w - lo_w)


def fit_critical_power_model(points, durations=(180, 300, 480, 720, 1200)):
    """Two-parameter critical-power field estimate from Intervals best efforts.

    The linearised model is P = CP + W'/t. CP is the intercept of power versus
    inverse time and W' is the slope (joules). This is deliberately labelled a
    *field model*: the source points may come from different rides and are not a
    controlled laboratory CP protocol.
    """
    pairs = []
    for sec in durations:
        watts = _power_at_duration(points, sec)
        if watts is not None:
            pairs.append((float(sec), float(watts)))
    if len(pairs) < 4:
        return {"available": False, "reason": "Need at least four usable best-effort durations between 3 and 20 min."}

    xs = [1.0 / sec for sec, _ in pairs]
    ys = [watts for _, watts in pairs]
    x_mean = statistics.mean(xs)
    y_mean = statistics.mean(ys)
    denom = sum((x - x_mean) ** 2 for x in xs)
    if denom <= 0:
        return {"available": False, "reason": "Power-curve durations are not sufficiently distinct."}
    slope = sum((x - x_mean) * (y - y_mean) for x, y in zip(xs, ys)) / denom
    intercept = y_mean - slope * x_mean
    preds = [intercept + slope * x for x in xs]
    sse = sum((y - pred) ** 2 for y, pred in zip(ys, preds))
    sst = sum((y - y_mean) ** 2 for y in ys)
    r2 = 1.0 - sse / sst if sst > 0 else 1.0
    errors = [abs(y - pred) / y * 100.0 for y, pred in zip(ys, preds) if y > 0]
    mae_pct = statistics.mean(errors) if errors else None

    cp = intercept
    w_prime_j = slope
    if not (50 <= cp <= 600 and 1000 <= w_prime_j <= 80000):
        return {"available": False, "reason": "The fitted parameters fell outside a plausible cycling field-model range."}
    if r2 >= 0.985 and len(pairs) >= 5:
        confidence = "HIGH"
    elif r2 >= 0.95:
        confidence = "MODERATE"
    else:
        confidence = "LOW"
    return {
        "available": True,
        "cp": round(cp),
        "w_prime_j": round(w_prime_j),
        "w_prime_kj": round(w_prime_j / 1000.0, 1),
        "r2": round(max(-1.0, min(1.0, r2)), 3),
        "mean_error_pct": round(mae_pct, 1) if mae_pct is not None else None,
        "confidence": confidence,
        "confidence_class": confidence.lower(),
        "points": [
            {"secs": int(sec), "label": format_duration_label(int(sec)), "watts": round(watts)}
            for sec, watts in pairs
        ],
    }


def build_power_model(points_42d, points_season, weight_kg=None):
    recent = fit_critical_power_model(points_42d)
    season = fit_critical_power_model(points_season)
    model = {
        "available": bool(recent.get("available")),
        "equation": "P = CP + W′ / t",
        "recent": recent,
        "season": season,
        "curve_comparison": [],
        "weight_kg": round(float(weight_kg), 1) if isinstance(weight_kg, (int, float)) else None,
        "cp_wkg": None,
        "season_cp_wkg": None,
        "cp_gap_w": None,
        "cp_proximity_pct": None,
        "status": "MODEL UNAVAILABLE",
        "status_class": "grey",
        "explanation": "Not enough usable best-effort points were returned for a stable 3–20 min two-parameter model.",
        "disclaimer": "Field estimate from Intervals.icu best-power curves; not a laboratory CP/W′ test.",
    }
    for sec in (300, 1200, 3600):
        w42 = _power_at_duration(points_42d, sec)
        ws = _power_at_duration(points_season, sec)
        if w42 is not None or ws is not None:
            model["curve_comparison"].append({
                "label": format_duration_label(sec),
                "recent": round(w42) if w42 is not None else None,
                "season": round(ws) if ws is not None else None,
            })
    if not recent.get("available"):
        return model

    if isinstance(weight_kg, (int, float)) and weight_kg > 0:
        model["cp_wkg"] = round(recent["cp"] / float(weight_kg), 2)
        if season.get("available"):
            model["season_cp_wkg"] = round(season["cp"] / float(weight_kg), 2)

    if season.get("available") and season.get("cp"):
        gap = recent["cp"] - season["cp"]
        proximity = recent["cp"] / season["cp"] * 100.0
        model["cp_gap_w"] = round(gap)
        model["cp_proximity_pct"] = round(proximity, 1)
        if proximity >= 99:
            status, css = "NEAR SEASON PEAK", "green"
        elif proximity >= 96:
            status, css = "CLOSE TO SEASON PEAK", "cyan"
        elif proximity >= 92:
            status, css = "BELOW SEASON PEAK", "orange"
        else:
            status, css = "WELL BELOW SEASON PEAK", "red"
        model["status"], model["status_class"] = status, css
        model["explanation"] = (
            f"The 42-day CP field model is {abs(round(gap))} W "
            f"{'above' if gap > 0 else 'below' if gap < 0 else 'at'} the current-season model "
            f"({proximity:.1f}% proximity). This compares recent best-power capacity with the season-best curve; it is not a readiness score."
        )
    else:
        model["status"], model["status_class"] = "42-DAY MODEL", "cyan"
        model["explanation"] = "A 42-day CP/W′ model is available, but the current-season comparison could not be fitted reliably."
    return model


def get_power_intelligence(weight_kg=None):
    """Fetch recent and current-season power curves once and build all power outputs.

    This replaces a duplicate 42-day call: Best Wattage Output and the CP/W′
    field model share the same recent payload; only the s0 current-season curve
    is the additional API request.
    """
    payloads = {}
    errors = []
    try:
        with ThreadPoolExecutor(max_workers=2) as pool:
            jobs = {
                pool.submit(fetch_power_curve_payload, None, "42d"): "42d",
                pool.submit(fetch_power_curve_payload, None, "s0"): "s0",
            }
            for future in as_completed(jobs):
                key = jobs[future]
                try:
                    payloads[key] = future.result()
                except Exception as exc:
                    errors.append(f"{key}: {exc}")
    except Exception as exc:
        errors.append(str(exc))

    points_42 = extract_power_curve_points(payloads.get("42d")) if payloads.get("42d") is not None else None
    points_s0 = extract_power_curve_points(payloads.get("s0")) if payloads.get("s0") is not None else None
    best = best_watts_for_durations(points_42, [5, 15, 60, 300, 1200, 3600]) if points_42 else []
    debug = None
    if not best:
        if errors:
            debug = "Power curve request failed: " + " | ".join(errors)
        elif payloads.get("42d") is not None:
            debug = "Power curve payload preview: " + json.dumps(payloads.get("42d"))[:500]
        else:
            debug = "42-day power curve unavailable."
    model = build_power_model(points_42 or [], points_s0 or [], weight_kg=weight_kg)
    if errors:
        model["api_note"] = " | ".join(errors)
    return best, debug, model


def fetch_intervals_data():
    """Fetch SEASON_DAYS_BACK days of activities (with zone times) AND
    wellness. Wellness needs the longer window too now, so we can learn the
    athlete's own normal range for Form/Fatigue instead of judging them
    against generic fixed thresholds. The recent-window subsets are simply
    the tail end of these season-length lists."""
    season_oldest = (date.today() - timedelta(days=SEASON_DAYS_BACK)).isoformat()
    recent_oldest = (date.today() - timedelta(days=DAYS_BACK)).isoformat()
    newest = date.today().isoformat()
    headers = get_intervals_headers()

    activities_fields = (
        "id,name,type,start_date_local,moving_time,elapsed_time,distance,"
        "icu_training_load,icu_weighted_avg_watts,average_watts,average_heartrate,"
        "icu_zone_times,icu_hr_zone_times,icu_hr_zones,icu_ftp,decoupling,"
        "calories,carbs_used,carbs_ingested,trainer,icu_intensity,"
        "icu_variability_index,joules,sub_type"
    )
    activities_url = (
        f"https://intervals.icu/api/v1/athlete/{ICU_ATHLETE_ID}/activities"
        f"?oldest={season_oldest}&newest={newest}&fields={activities_fields}"
    )

    wellness_fields = "id,restingHR,hrv,sleepSecs,sleepScore,sleepQuality,avgSleepingHR,weight,ctl,atl,rampRate,comments,readiness,spO2,vo2max,sportInfo"
    wellness_url = (
        f"https://intervals.icu/api/v1/athlete/{ICU_ATHLETE_ID}/wellness"
        f"?oldest={season_oldest}&newest={newest}&fields={wellness_fields}"
    )

    act_resp = requests.get(activities_url, headers=headers, timeout=30)
    act_resp.raise_for_status()
    wel_resp = requests.get(wellness_url, headers=headers, timeout=30)
    wel_resp.raise_for_status()

    season_activities = act_resp.json()
    season_activities = [
        a for a in season_activities if a.get("start_date_local", "")[:10] >= season_oldest
    ]
    recent_activities = [
        a for a in season_activities if a.get("start_date_local", "")[:10] >= recent_oldest
    ]

    season_wellness = wel_resp.json()
    season_wellness = [
        w for w in season_wellness if w.get("id", "") >= season_oldest
    ]
    recent_wellness = [w for w in season_wellness if w.get("id", "") >= recent_oldest]

    return recent_activities, season_activities, recent_wellness, season_wellness


def _vo2_number(value):
    try:
        value = float(value)
    except (TypeError, ValueError):
        return None
    # Sanity filter only; this is not a physiological classification.
    return value if 15.0 <= value <= 100.0 else None


def extract_vo2max_5m(payload):
    """Return Intervals.icu's performance VO2max estimate from a power curve.

    The Intervals.icu server-side power-curve model exposes ``vo2max_5m``.
    The public endpoint payload can contain nested curve objects, so search
    recursively and keep a plausible numeric value. The URL asks only for the
    42-day Ride curve; if several nested representations are present we retain
    the highest identical/near-identical estimate rather than inventing a
    value from average power.
    """
    values = []

    def walk(node):
        if isinstance(node, dict):
            if "vo2max_5m" in node:
                v = _vo2_number(node.get("vo2max_5m"))
                if v is not None:
                    values.append(v)
            for value in node.values():
                walk(value)
        elif isinstance(node, list):
            for item in node:
                walk(item)

    walk(payload)
    return round(max(values), 1) if values else None


def _sample_vo2_points(points, max_points=10):
    if len(points) <= max_points:
        return points
    if max_points <= 1:
        return [points[-1]]
    # Evenly retain the full time span, always keeping first and latest.
    idxs = []
    for i in range(max_points):
        idx = round(i * (len(points) - 1) / (max_points - 1))
        if idx not in idxs:
            idxs.append(idx)
    return [points[i] for i in idxs]


def build_wearable_vo2_series(wellness, max_points=10):
    """VO2max imported through Intervals wellness (typically wearable data).

    Consecutive identical values are collapsed to the *latest* date carrying
    that value. This keeps the chart readable instead of printing the same
    wearable estimate on dozens of consecutive days.
    """
    raw = []
    for w in sorted(wellness or [], key=lambda x: x.get("id", "")):
        v = _vo2_number(w.get("vo2max"))
        day = str(w.get("id") or "")[:10]
        if v is None or len(day) != 10:
            continue
        item = {"date": day, "value": round(v, 1)}
        if raw and abs(raw[-1]["value"] - item["value"]) < 0.05:
            raw[-1] = item
        else:
            raw.append(item)
    return _sample_vo2_points(raw, max_points=max_points)


def _performance_vo2_checkpoint(day):
    payload = fetch_power_curve_payload(newest=day.isoformat())
    value = extract_vo2max_5m(payload)
    return {"date": day.isoformat(), "value": value} if value is not None else None


def build_performance_vo2_series(points=8, step_days=7):
    """Historical Intervals 5-minute-power VO2max trend.

    Intervals' athlete power-curve endpoint accepts ``newest`` and the 42-day
    curve carries ``vo2max_5m``. Query a small number of weekly checkpoints in
    parallel. This is intentionally low-resolution: it is a longitudinal
    context signal, not a readiness metric and not a laboratory measurement.
    """
    today = date.today()
    checkpoints = [today - timedelta(days=step_days * i) for i in reversed(range(points))]
    results = []
    try:
        with ThreadPoolExecutor(max_workers=4) as pool:
            futures = {pool.submit(_performance_vo2_checkpoint, d): d for d in checkpoints}
            for future in as_completed(futures):
                try:
                    item = future.result()
                    if item:
                        results.append(item)
                except Exception:
                    # One failed historical checkpoint must never break a snapshot.
                    pass
    except Exception:
        return []
    results.sort(key=lambda x: x["date"])
    # Rolling 42-day values often remain unchanged for several checkpoints.
    # Keep all weekly checkpoints because the flat portions are meaningful.
    return results


def _vo2_delta_28(series):
    if len(series) < 2:
        return None
    latest = series[-1]
    try:
        latest_day = date.fromisoformat(latest["date"])
    except Exception:
        return None
    target = latest_day - timedelta(days=28)
    candidates = []
    for p in series[:-1]:
        try:
            d = date.fromisoformat(p["date"])
        except Exception:
            continue
        candidates.append((abs((d - target).days), d, p))
    if not candidates:
        return None
    _, _, base = min(candidates, key=lambda x: x[0])
    return round(latest["value"] - base["value"], 1)


def _vo2_direction(delta):
    if delta is None:
        return None
    if delta >= 0.5:
        return "RISING"
    if delta <= -0.5:
        return "FALLING"
    return "STABLE"


def _vo2_path(points):
    return " ".join(("M" if i == 0 else "L") + f" {p['x']:.1f} {p['y']:.1f}" for i, p in enumerate(points))


def build_vo2max_trend(season_wellness):
    wearable = build_wearable_vo2_series(season_wellness, max_points=10)
    performance = build_performance_vo2_series(points=8, step_days=7)

    all_points = wearable + performance
    if not all_points:
        return {
            "available": False, "wearable": [], "performance": [],
            "wearable_current": None, "performance_current": None,
            "wearable_delta28": None, "performance_delta28": None,
            "agreement": "INSUFFICIENT DATA", "agreement_class": "grey",
        }

    dated = []
    for p in all_points:
        try:
            dated.append((date.fromisoformat(p["date"]), float(p["value"])))
        except Exception:
            pass
    if not dated:
        return {"available": False, "wearable": [], "performance": [], "agreement": "INSUFFICIENT DATA", "agreement_class": "grey"}

    min_day = min(d for d, _ in dated)
    max_day = max(d for d, _ in dated)
    day_span = max(1, (max_day - min_day).days)
    values = [v for _, v in dated]
    vmin, vmax = min(values), max(values)
    pad = max(1.0, (vmax - vmin) * 0.18)
    ymin = math.floor((vmin - pad) * 2) / 2
    ymax = math.ceil((vmax + pad) * 2) / 2
    if ymax - ymin < 4:
        mid = (ymax + ymin) / 2
        ymin, ymax = mid - 2, mid + 2

    x0, x1 = 58.0, 942.0
    y0, y1 = 32.0, 188.0

    def map_series(series, label_offset):
        mapped = []
        for p in series:
            d = date.fromisoformat(p["date"])
            x = x0 + ((d - min_day).days / day_span) * (x1 - x0)
            y = y1 - ((p["value"] - ymin) / (ymax - ymin)) * (y1 - y0)
            mapped.append({
                **p,
                "x": round(x, 1), "y": round(y, 1),
                "label_y": round(max(17, min(211, y + label_offset)), 1),
                "date_label": d.strftime("%d %b"),
                "value_label": f"{p['value']:.1f}",
            })
        return mapped

    wearable_m = map_series(wearable, -12)
    performance_m = map_series(performance, 21)
    wd = _vo2_delta_28(wearable)
    pd = _vo2_delta_28(performance)
    wdir, pdir = _vo2_direction(wd), _vo2_direction(pd)
    if wdir is None or pdir is None:
        agreement = "INSUFFICIENT DATA"
        agreement_class = "grey"
    elif wdir == "RISING" and pdir == "RISING":
        agreement, agreement_class = "BOTH RISING", "green"
    elif wdir == "STABLE" and pdir == "STABLE":
        agreement, agreement_class = "BOTH STABLE", "cyan"
    elif {wdir, pdir} == {"RISING", "FALLING"}:
        agreement, agreement_class = "DIVERGING", "orange"
    else:
        agreement, agreement_class = "MIXED", "grey"

    ticks = []
    for frac in (0.0, 0.5, 1.0):
        value = ymax - frac * (ymax - ymin)
        ticks.append({"y": round(y0 + frac * (y1 - y0), 1), "value": round(value, 1)})

    date_ticks = []
    for frac in (0.0, 0.5, 1.0):
        d = min_day + timedelta(days=round(day_span * frac))
        date_ticks.append({"x": round(x0 + frac * (x1 - x0), 1), "label": d.strftime("%d %b")})

    return {
        "available": True,
        "wearable": wearable_m,
        "performance": performance_m,
        "wearable_path": _vo2_path(wearable_m) if wearable_m else "",
        "performance_path": _vo2_path(performance_m) if performance_m else "",
        "wearable_current": wearable[-1]["value"] if wearable else None,
        "performance_current": performance[-1]["value"] if performance else None,
        "wearable_delta28": wd,
        "performance_delta28": pd,
        "wearable_direction": wdir or "INSUFFICIENT",
        "performance_direction": pdir or "INSUFFICIENT",
        "agreement": agreement,
        "agreement_class": agreement_class,
        "ticks": ticks,
        "date_ticks": date_ticks,
        "ymin": ymin, "ymax": ymax,
    }


def percentile(sorted_values, pct):
    """Simple linear-interpolation percentile, no numpy dependency."""
    if not sorted_values:
        return None
    if len(sorted_values) == 1:
        return sorted_values[0]
    k = (len(sorted_values) - 1) * pct
    f, c = int(k), min(int(k) + 1, len(sorted_values) - 1)
    if f == c:
        return sorted_values[f]
    return sorted_values[f] + (sorted_values[c] - sorted_values[f]) * (k - f)


def personal_form_thresholds(season_wellness, min_points=14):
    """The athlete's own p33/p67 TSB range over the season window, so Form is
    judged against their normal baseline instead of a generic cutoff."""
    tsb_values = sorted(
        w["ctl"] - w["atl"] for w in season_wellness
        if w.get("ctl") is not None and w.get("atl") is not None
    )
    if len(tsb_values) < min_points:
        return None
    return percentile(tsb_values, 0.33), percentile(tsb_values, 0.67)


def personal_form_median(season_wellness, min_points=14):
    """The athlete's own typical TSB, so day-to-day form can be shown as a
    small delta from what's normal FOR THEM instead of a scary absolute
    number that's just a side effect of training at chronic high load."""
    tsb_values = sorted(
        w["ctl"] - w["atl"] for w in season_wellness
        if w.get("ctl") is not None and w.get("atl") is not None
    )
    if len(tsb_values) < min_points:
        return None
    return percentile(tsb_values, 0.5)


def personal_fatigue_thresholds(season_wellness, min_points=14):
    """The athlete's own p33/p67 ATL:CTL ratio range over the season window."""
    ratios = sorted(
        w["atl"] / w["ctl"] for w in season_wellness
        if w.get("ctl") not in (None, 0) and w.get("atl") is not None
    )
    if len(ratios) < min_points:
        return None
    return percentile(ratios, 0.33), percentile(ratios, 0.67)


def classify_form(tsb, personal_thresholds=None):
    if tsb is None:
        return "grey"
    if personal_thresholds:
        p33, p67 = personal_thresholds
        if tsb >= p67:
            return "green"
        if tsb <= p33:
            return "red"
        return "grey"
    # Fallback generic thresholds - only used when there isn't enough
    # history yet to learn the athlete's own normal range.
    if tsb >= 5:
        return "green"
    if tsb <= -10:
        return "red"
    return "grey"


def classify_fatigue(atl, ctl, personal_thresholds=None):
    if atl is None or ctl is None or ctl == 0:
        return "grey"
    ratio = atl / ctl
    if personal_thresholds:
        p33, p67 = personal_thresholds
        if ratio <= p33:
            return "green"
        if ratio >= p67:
            return "red"
        return "grey"
    if ratio >= 1.15:
        return "red"
    if ratio <= 0.95:
        return "green"
    return "grey"


def classify_fitness_trend(wellness):
    ctl_values = [(w.get("id"), w.get("ctl")) for w in wellness if w.get("ctl") is not None]
    ctl_values.sort(key=lambda x: x[0])
    if len(ctl_values) < 2:
        return "grey"
    change = ctl_values[-1][1] - ctl_values[0][1]
    if change >= 2:
        return "green"
    if change <= -2:
        return "red"
    return "grey"


def bucket_zone_seconds(zone_seconds):
    """Given an ordered list of seconds-per-zone (easiest to hardest), bucket
    into Low / Moderate / High using common Coggan-style zone groupings."""
    n = len(zone_seconds)
    if n == 0:
        return 0, 0, 0
    if n == 3:
        low, mod, high = zone_seconds[0], zone_seconds[1], zone_seconds[2]
    elif n in (5, 6):
        low = sum(zone_seconds[0:2])
        mod = zone_seconds[2] if n == 5 else sum(zone_seconds[2:4])
        high = sum(zone_seconds[3:]) if n == 5 else sum(zone_seconds[4:])
    elif n == 7:
        low = sum(zone_seconds[0:2])
        mod = sum(zone_seconds[2:4])
        high = sum(zone_seconds[4:])
    else:
        third = max(1, n // 3)
        low = sum(zone_seconds[0:third])
        mod = sum(zone_seconds[third:2 * third])
        high = sum(zone_seconds[2 * third:])
    return low, mod, high


def compute_season_stats(season_activities):
    total_secs = 0
    low_secs = mod_secs = high_secs = 0
    total_load = 0

    for a in season_activities:
        total_secs += a.get("moving_time") or a.get("elapsed_time") or 0
        total_load += a.get("icu_training_load") or 0
        zt = a.get("icu_zone_times")
        if zt:
            secs_list = [z.get("secs", 0) for z in zt]
            low, mod, high = bucket_zone_seconds(secs_list)
            low_secs += low
            mod_secs += mod
            high_secs += high

    zone_total = low_secs + mod_secs + high_secs
    if zone_total > 0:
        low_pct = round(100 * low_secs / zone_total)
        mod_pct = round(100 * mod_secs / zone_total)
        high_pct = round(100 * high_secs / zone_total)
    else:
        low_pct = mod_pct = high_pct = None

    return {
        "season_hours": round(total_secs / 3600, 1),
        "season_total_load": round(total_load),
        "zone_low_pct": low_pct if low_pct is not None else "n/a",
        "zone_mod_pct": mod_pct if mod_pct is not None else "n/a",
        "zone_high_pct": high_pct if high_pct is not None else "n/a",
    }


def last_two_values(wellness, field):
    vals = [
        w[field] for w in sorted(wellness, key=lambda x: x.get("id", ""))
        if w.get(field) is not None
    ]
    if len(vals) < 2:
        return None, None
    return vals[-1], vals[-2]


def trend_arrow(current, previous, higher_is_better):
    """higher_is_better: True/False for a directional judgement, or None for
    a neutral metric where up/down isn't inherently good or bad."""
    if current is None or previous is None or current == previous:
        return None
    up = current > previous
    arrow = "▲" if up else "▼"
    if higher_is_better is None:
        color = "grey"
    else:
        good = up if higher_is_better else not up
        color = "green" if good else "red"
    return {"arrow": arrow, "color": color}


def _recent_numeric(wellness, field, days=RECENT_BASELINE_DAYS, exclude_latest=True, divisor=1.0):
    """Numeric recent values for trend context, independent from Garmin's fixed personal baseline."""
    ordered = sorted(wellness, key=lambda x: x.get("id", ""))
    if exclude_latest and ordered:
        ordered = ordered[:-1]
    vals = []
    for w in ordered:
        value = w.get(field)
        if isinstance(value, (int, float)):
            vals.append(value / divisor)
    return vals[-days:]


def _fmt_hours(hours):
    if not isinstance(hours, (int, float)):
        return "n/a"
    total = max(0, round(hours * 60))
    return f"{total // 60}h {total % 60:02d}m"


def _fmt_number(value, decimals=0, suffix=""):
    if not isinstance(value, (int, float)):
        return "n/a"
    rendered = f"{value:.{decimals}f}" if decimals else str(round(value))
    return f"{rendered}{suffix}"



def _median_minutes(values):
    vals = [float(v) for v in values if isinstance(v, (int, float)) and 180 <= float(v) <= 720]
    return statistics.median(vals) if vals else None


def _sleep_iqr_label(values):
    vals = sorted(float(v) for v in values if isinstance(v, (int, float)) and 180 <= float(v) <= 720)
    if len(vals) < 4:
        return None
    q1, _, q3 = statistics.quantiles(vals, n=4, method="inclusive")
    return f"{_fmt_hours(q1 / 60.0)}–{_fmt_hours(q3 / 60.0)}"


def build_adaptive_sleep_baseline(wellness, lookback_days=SLEEP_BASELINE_DAYS):
    """Learn the athlete's realistic sleep opportunity from their own history.

    Weekdays and weekends are separated because work/life constraints can make
    the attainable sleep opportunity structurally different. Garmin's 7h38m
    reference is retained as a reference only; the daily recovery penalty is
    driven by the matching habitual baseline instead of an aspirational target.
    """
    rows = []
    for w in sorted(wellness or [], key=lambda x: str(x.get("id") or "")):
        raw_day = str(w.get("id") or "")[:10]
        secs = w.get("sleepSecs")
        if not isinstance(secs, (int, float)) or not raw_day:
            continue
        try:
            d = date.fromisoformat(raw_day)
        except Exception:
            continue
        minutes = float(secs) / 60.0
        if not 180 <= minutes <= 720:
            continue
        rows.append({"date": d, "minutes": minutes, "kind": "WEEKDAY" if d.weekday() < 5 else "WEEKEND"})

    if not rows:
        return {
            "available": False, "days": lookback_days, "kind": "UNKNOWN",
            "current_minutes": None, "habitual_minutes": None, "current_delta_min": None,
            "weekday_minutes": None, "weekend_minutes": None, "overall_minutes": None,
            "weekday_label": "n/a", "weekend_label": "n/a", "overall_label": "n/a",
            "weekday_iqr": None, "weekend_iqr": None, "status": "NO DATA", "color": "grey", "pct": 0,
            "reference_minutes": GARMIN_BASELINES["sleep_minutes"], "reference_label": "7h 38m",
            "reference_delta_min": None, "sample_count": 0, "weekday_samples": 0, "weekend_samples": 0,
            "trend_label": "NO TREND", "trend_delta_min": None,
        }

    current = rows[-1]
    cutoff = current["date"] - timedelta(days=lookback_days)
    baseline_rows = [r for r in rows[:-1] if r["date"] >= cutoff]
    if not baseline_rows:
        baseline_rows = rows[:-1]

    weekday = [r["minutes"] for r in baseline_rows if r["kind"] == "WEEKDAY"]
    weekend = [r["minutes"] for r in baseline_rows if r["kind"] == "WEEKEND"]
    overall = [r["minutes"] for r in baseline_rows]
    overall_median = _median_minutes(overall)
    weekday_median = _median_minutes(weekday) if len(weekday) >= 5 else overall_median
    weekend_median = _median_minutes(weekend) if len(weekend) >= 2 else overall_median
    habitual = weekday_median if current["kind"] == "WEEKDAY" else weekend_median
    delta = current["minutes"] - habitual if habitual is not None else None

    if delta is None:
        status, color, pct = "INSUFFICIENT DATA", "grey", 0
    else:
        # A modest night-to-night swing is normal. Only meaningful deviation
        # from the athlete's own opportunity baseline earns a penalty.
        if delta >= -20:
            status, color = "WITHIN HABITUAL", "green"
        elif delta >= -45:
            status, color = "SLIGHTLY SHORT", "grey"
        elif delta >= -75:
            status, color = "SHORT VS HABITUAL", "orange"
        else:
            status, color = "WELL BELOW HABITUAL", "red"
        pct = max(10, min(100, round(current["minutes"] / habitual * 100))) if habitual else 0

    # Short rolling trend, deliberately separate from the weekday/weekend baseline.
    prior_values = [r["minutes"] for r in rows[:-1]][-28:]
    recent14 = prior_values[-14:]
    prior14 = prior_values[-28:-14]
    trend_delta = None
    trend_label = "NO TREND"
    if len(recent14) >= 5 and len(prior14) >= 5:
        trend_delta = round(statistics.mean(recent14) - statistics.mean(prior14))
        if trend_delta >= 15:
            trend_label = "LONGER"
        elif trend_delta <= -15:
            trend_label = "SHORTER"
        else:
            trend_label = "STABLE"

    ref_delta = round(current["minutes"] - GARMIN_BASELINES["sleep_minutes"])
    return {
        "available": habitual is not None,
        "days": lookback_days,
        "kind": current["kind"],
        "current_minutes": round(current["minutes"]),
        "habitual_minutes": round(habitual) if habitual is not None else None,
        "current_delta_min": round(delta) if delta is not None else None,
        "weekday_minutes": round(weekday_median) if weekday_median is not None else None,
        "weekend_minutes": round(weekend_median) if weekend_median is not None else None,
        "overall_minutes": round(overall_median) if overall_median is not None else None,
        "weekday_label": _fmt_hours(weekday_median / 60.0) if weekday_median is not None else "n/a",
        "weekend_label": _fmt_hours(weekend_median / 60.0) if weekend_median is not None else "n/a",
        "overall_label": _fmt_hours(overall_median / 60.0) if overall_median is not None else "n/a",
        "weekday_iqr": _sleep_iqr_label(weekday),
        "weekend_iqr": _sleep_iqr_label(weekend),
        "habitual_label": _fmt_hours(habitual / 60.0) if habitual is not None else "n/a",
        "status": status, "color": color, "pct": pct,
        "reference_minutes": GARMIN_BASELINES["sleep_minutes"], "reference_label": "7h 38m",
        "reference_delta_min": ref_delta,
        "sample_count": len(baseline_rows), "weekday_samples": len(weekday), "weekend_samples": len(weekend),
        "trend_label": trend_label, "trend_delta_min": trend_delta,
    }


def _range_signal(value, low, high, kind="neutral"):
    """Status versus a personal Garmin range. The ring expresses closeness to normal, not 'performance'."""
    if not isinstance(value, (int, float)):
        return {"color": "grey", "status": "No current data", "pct": 0}
    width = max(high - low, 1)
    if low <= value <= high:
        return {"color": "green", "status": "Within baseline", "pct": 100}
    if value < low:
        distance = low - value
        pct = max(10, round(100 - (distance / width) * 75))
        if kind == "hrv":
            color = "red" if distance > width * 0.25 else "grey"
            status = "Below baseline"
        elif kind == "heart_rate":
            color = "grey" if distance <= 3 else "red"
            status = "Below baseline"
        else:
            color, status = "grey", "Below baseline"
        return {"color": color, "status": status, "pct": pct}
    distance = value - high
    pct = max(10, round(100 - (distance / width) * 75))
    if kind == "hrv":
        color = "green" if distance <= width * 0.25 else "grey"
        status = "Above baseline"
    elif kind == "heart_rate":
        color = "red" if distance > 2 else "grey"
        status = "Above baseline"
    else:
        color, status = "grey", "Above baseline"
    return {"color": color, "status": status, "pct": pct}


def _target_signal(value, target, metric):
    if not isinstance(value, (int, float)):
        return {"color": "grey", "status": "No current data", "pct": 0}
    if metric == "sleep_minutes":
        diff = value - target
        pct = max(10, min(100, round(value / target * 100))) if target else 0
        if diff >= -30:
            return {"color": "green", "status": "On target", "pct": pct}
        if diff >= -75:
            return {"color": "grey", "status": "Below target", "pct": pct}
        return {"color": "red", "status": "Short sleep", "pct": pct}
    if metric == "sleep_score":
        pct = max(10, min(100, round(value)))
        if value >= target - 3:
            return {"color": "green", "status": "Near baseline", "pct": pct}
        if value >= target - 10:
            return {"color": "grey", "status": "Below baseline", "pct": pct}
        return {"color": "red", "status": "Low vs baseline", "pct": pct}
    if metric == "spo2":
        pct = max(10, min(100, round(value)))
        if value >= target - 1:
            return {"color": "green", "status": "Near baseline", "pct": pct}
        if value >= target - 2:
            return {"color": "grey", "status": "Below baseline", "pct": pct}
        return {"color": "red", "status": "Low vs baseline", "pct": pct}
    return {"color": "grey", "status": "Reference", "pct": 0}


def compute_personal_baselines(wellness):
    """Personal physiology references plus rolling context.

    HRV/RHR retain the athlete's Garmin ranges. Sleep is intentionally different:
    the fixed 7h38m Garmin reference remains visible, but day-to-day interpretation
    uses a 42-day weekday/weekend habitual baseline learned from the athlete's own
    sleep opportunity.
    """
    ordered = sorted(wellness, key=lambda x: x.get("id", ""))
    latest = ordered[-1] if ordered else {}

    hrv_recent = _recent_numeric(wellness, "hrv")
    rhr_recent = _recent_numeric(wellness, "restingHR")
    score_recent = _recent_numeric(wellness, "sleepScore")
    spo2_recent = _recent_numeric(wellness, "spO2")
    sleeping_hr_recent = _recent_numeric(wellness, "avgSleepingHR")

    current_rhr = latest.get("restingHR")
    current_hrv = latest.get("hrv")
    current_score = latest.get("sleepScore")
    current_sleeping_hr = latest.get("avgSleepingHR")
    spo2_entries = [w for w in ordered if isinstance(w.get("spO2"), (int, float))]
    current_spo2 = spo2_entries[-1].get("spO2") if spo2_entries else None

    rhr_signal = _range_signal(current_rhr, GARMIN_BASELINES["resting_hr_low"], GARMIN_BASELINES["resting_hr_high"], "heart_rate")
    hrv_signal = _range_signal(current_hrv, GARMIN_BASELINES["hrv_low"], GARMIN_BASELINES["hrv_high"], "hrv")
    adaptive_sleep = build_adaptive_sleep_baseline(wellness)
    sleep_signal = {
        "color": adaptive_sleep.get("color", "grey"),
        "status": adaptive_sleep.get("status", "No current data"),
        "pct": adaptive_sleep.get("pct", 0),
    }
    score_signal = _target_signal(current_score, GARMIN_BASELINES["sleep_score"], "sleep_score")
    spo2_signal = _target_signal(current_spo2, GARMIN_BASELINES["spo2"], "spo2")
    sleeping_hr_signal = _range_signal(current_sleeping_hr, GARMIN_BASELINES["resting_hr_low"], GARMIN_BASELINES["resting_hr_high"], "heart_rate")

    return {
        "source": BASELINE_SOURCE,
        "days": RECENT_BASELINE_DAYS,
        "rhr": {**rhr_signal, "garmin": "38–44 bpm", "recent": _fmt_number(statistics.median(rhr_recent), 0, " bpm") if rhr_recent else "n/a"},
        "hrv": {**hrv_signal, "garmin": "89–136 ms", "recent": _fmt_number(statistics.median(hrv_recent), 0, " ms") if hrv_recent else "n/a"},
        "sleep": {
            **sleep_signal,
            "garmin": "7h 38m reference",
            "recent": f"{adaptive_sleep.get('kind', 'habitual').title()} habitual {adaptive_sleep.get('habitual_label', 'n/a')}",
            "habitual_minutes": adaptive_sleep.get("habitual_minutes"),
            "habitual_label": adaptive_sleep.get("habitual_label"),
            "current_delta_min": adaptive_sleep.get("current_delta_min"),
            "adaptive": adaptive_sleep,
        },
        "sleep_score": {**score_signal, "garmin": "86", "recent": _fmt_number(statistics.mean(score_recent), 0) if score_recent else "n/a"},
        "spo2": {**spo2_signal, "garmin": "97%", "recent": _fmt_number(statistics.median(spo2_recent), 1, "%") if spo2_recent else "n/a"},
        "sleeping_hr": {**sleeping_hr_signal, "garmin": "38–44 bpm", "recent": _fmt_number(statistics.median(sleeping_hr_recent), 0, " bpm") if sleeping_hr_recent else "n/a"},
        "sleeping_respiration": {"garmin": "11 brpm", "recent": "not synced", "color": "grey", "status": "Garmin reference only", "pct": 0},
        "awake_respiration": {"garmin": "13–14 brpm", "recent": "not synced", "color": "grey", "status": "Garmin reference only", "pct": 0},
        "adaptive_sleep": adaptive_sleep,
    }

def compute_health_rings(metrics):
    """Small rings now show closeness to the athlete's Garmin baseline, while arrows still show day-to-day direction."""
    pb = metrics.get("personal_baselines") or {}
    rings = {}
    for key in ("rhr", "hrv", "sleep"):
        item = pb.get(key)
        if item:
            rings[key] = {"pct": item.get("pct", 0), "color": item.get("color", "grey"), "status": item.get("status", "Reference")}
    return rings

def compute_trend_arrows(wellness):
    rhr_latest, rhr_prev = last_two_values(wellness, "restingHR")
    hrv_latest, hrv_prev = last_two_values(wellness, "hrv")
    sleep_latest, sleep_prev = last_two_values(wellness, "sleepSecs")
    weight_latest, weight_prev = last_two_values(wellness, "weight")
    return {
        "rhr": trend_arrow(rhr_latest, rhr_prev, higher_is_better=False),
        "hrv": trend_arrow(hrv_latest, hrv_prev, higher_is_better=True),
        "sleep": trend_arrow(sleep_latest, sleep_prev, higher_is_better=True),
        "weight": trend_arrow(weight_latest, weight_prev, higher_is_better=None),
    }


def compute_recent_trend(wellness, n=5, form_thresholds=None, form_median=None):
    """Daily Form (TSB) for the last n days that have both CTL and ATL, for a
    quick at-a-glance trend next to the Energy Bank. Shown primarily as a
    delta from the athlete's own typical TSB, not the raw absolute number -
    for someone who trains at chronic high load, the raw number is nearly
    always a scary-looking double-digit negative even on a completely
    ordinary day."""
    daily = []
    for w in sorted(wellness, key=lambda x: x.get("id", "")):
        ctl, atl = w.get("ctl"), w.get("atl")
        if ctl is None or atl is None:
            continue
        tsb = round(ctl - atl, 1)
        try:
            weekday = date.fromisoformat(w["id"]).strftime("%a")
        except (ValueError, KeyError):
            weekday = w.get("id", "")[-2:]
        delta = round(tsb - form_median, 1) if form_median is not None else None
        daily.append({
            "date": w.get("id", ""), "weekday": weekday, "tsb": tsb, "delta": delta,
            "zone": classify_form(tsb, form_thresholds),
        })
    return daily[-n:]


def compute_energy_bank(form_zone, fatigue_zone, avg_sleep_hours, recent_activities=None, personal_baselines=None, now=None, sleep_quality=None):
    """Intraday 0-100 energy estimate.

    Morning recovery establishes the potential available for the day. Completed
    activities then spend that potential using Intervals.icu training load,
    duration and session type. Sleep quality is intentionally weighted strongly:
    a good-quality night can partially offset a modest duration deficit, while a
    poor-quality night remains a meaningful recovery penalty.
    """
    now = now or get_rome_now()
    recent_activities = recent_activities or []
    pb = personal_baselines or {}

    # Morning potential. Duration matters, but quality is a first-class signal.
    morning = 62
    morning += {"green": 12, "grey": 0, "red": -14}.get(form_zone, 0)
    morning += {"green": 9, "grey": 0, "red": -11}.get(fatigue_zone, 0)

    if isinstance(avg_sleep_hours, (int, float)):
        sleep_target_minutes = (pb.get("sleep") or {}).get("habitual_minutes")
        if isinstance(sleep_target_minutes, (int, float)) and sleep_target_minutes > 0:
            sleep_delta = avg_sleep_hours * 60.0 - sleep_target_minutes
            if sleep_delta >= 20:
                morning += 3
            elif sleep_delta < -75:
                morning -= 6
            elif sleep_delta < -45:
                morning -= 3
            elif sleep_delta < -20:
                morning -= 1
        else:
            # Conservative fallback only when there is not enough history to learn
            # the athlete's attainable sleep opportunity.
            if avg_sleep_hours >= 7.5:
                morning += 4
            elif avg_sleep_hours < 6.5:
                morning -= 6
            elif avg_sleep_hours < 7.0:
                morning -= 2

    # Q1/Q2 are intentionally meaningful because weekday sleep duration is often
    # constrained by the athlete's routine. Good quality should prevent a modest
    # short night from being treated as automatically poor recovery.
    if sleep_quality == 1:
        morning += 10
    elif sleep_quality == 2:
        morning += 7
    elif sleep_quality == 3:
        morning -= 3
    elif sleep_quality == 4:
        morning -= 10

    # Recovery signals affect the starting reserve, not the training cost.
    hrv = pb.get("hrv", {})
    rhr = pb.get("rhr", {})
    sleep = pb.get("sleep", {})
    if hrv.get("color") == "red": morning -= 10
    elif hrv.get("color") == "grey": morning -= 4
    if rhr.get("color") == "red": morning -= 7
    elif rhr.get("color") == "grey" and rhr.get("status") == "Above baseline": morning -= 3

    if sleep.get("color") == "red":
        morning -= 2 if sleep_quality in (1, 2) else 7
    elif sleep.get("color") == "grey":
        morning -= 0 if sleep_quality in (1, 2) else 3

    morning = max(25, min(96, round(morning)))

    today = now.date().isoformat()
    today_activities = [a for a in recent_activities if str(a.get("start_date_local", ""))[:10] == today]
    today_load = 0.0
    today_minutes = 0.0
    hard_sessions = 0
    for a in today_activities:
        load = a.get("icu_training_load")
        if isinstance(load, (int, float)):
            today_load += max(0, float(load))
        secs = a.get("moving_time") or a.get("elapsed_time") or 0
        if isinstance(secs, (int, float)):
            today_minutes += max(0, float(secs)) / 60.0
        try:
            family = classify_training_family(a)
            if is_hard_training_family(family):
                hard_sessions += 1
        except Exception:
            pass

    load_cost = min(40, today_load * 0.30)
    duration_cost = min(12, max(0, today_minutes - 45) * 0.045)
    session_cost = max(0, len(today_activities) - 1) * 5
    hard_cost = hard_sessions * 5
    spent = min(62, load_cost + duration_cost + session_cost + hard_cost)

    score = max(5, min(100, round(morning - spent)))
    if score >= 72:
        label, zone = "Charged", "green"
    elif score >= 45:
        label, zone = "Available", "grey"
    elif score >= 25:
        label, zone = "Used", "orange"
    else:
        label, zone = "Drained", "red"

    theta = math.pi - (score / 100.0) * math.pi
    marker_radius = 87
    marker_x = round(100 + marker_radius * math.cos(theta), 1)
    marker_y = round(95 - marker_radius * math.sin(theta), 1)

    return {
        "energy_score": score, "energy_label": label, "energy_zone": zone,
        "marker_x": marker_x, "marker_y": marker_y,
        "energy_morning_score": morning,
        "energy_today_load": round(today_load),
        "energy_today_minutes": round(today_minutes),
        "energy_today_sessions": len(today_activities),
        "energy_spent": round(spent),
        "energy_sleep_quality": sleep_quality,
    }

def sleep_quality_details(value):
    """Intervals.icu sleepQuality: 1=Excellent, 2=Good, 3=Average, 4=Poor."""
    try:
        q = int(float(value))
    except (TypeError, ValueError):
        return "Q–", "No quality data", "qna"
    labels = {1: "Excellent", 2: "Good", 3: "Average", 4: "Poor"}
    q = max(1, min(4, q))
    return f"Q{q}", labels[q], f"q{q}"


def compute_race_readiness(form_zone, fatigue_zone, sleep_quality, personal_baselines):
    """0-100 readiness with a concise explanation; detailed baselines live elsewhere in the UI."""
    score = 50
    signals = []
    score += {"green": 18, "grey": 0, "red": -18}.get(form_zone, 0)
    score += {"green": 15, "grey": 0, "red": -15}.get(fatigue_zone, 0)

    # Sleep quality has deliberate weight. A Q1/Q2 night is meaningful even when
    # duration is modestly below the weekday target.
    if sleep_quality == 1:
        score += 12
    elif sleep_quality == 2:
        score += 9
    elif sleep_quality == 3:
        score -= 3; signals.append((2, "sleep quality average"))
    elif sleep_quality == 4:
        score -= 10; signals.append((3, "sleep quality poor"))

    pb = personal_baselines or {}
    hrv, rhr, sleep, spo2 = (pb.get(k, {}) for k in ("hrv", "rhr", "sleep", "spo2"))

    if hrv.get("status") == "Within baseline": score += 6
    elif hrv.get("status") == "Above baseline": score += 5
    elif hrv.get("status") == "Below baseline":
        score += -9 if hrv.get("color") == "red" else -4
        signals.append((3 if hrv.get("color") == "red" else 2, "HRV below personal range"))

    if rhr.get("status") == "Within baseline": score += 4
    elif rhr.get("status") == "Above baseline":
        score += -8 if rhr.get("color") == "red" else -3
        signals.append((3 if rhr.get("color") == "red" else 2, "resting HR elevated"))

    if sleep.get("color") == "green":
        score += 4
    elif sleep.get("color") == "grey":
        if sleep_quality not in (1, 2):
            score -= 3; signals.append((1, "sleep slightly short"))
    elif sleep.get("color") == "red":
        if sleep_quality in (1, 2):
            score -= 3; signals.append((1, "sleep short but quality good"))
        else:
            score -= 8; signals.append((3, "sleep well below habitual opportunity"))

    if spo2.get("status") != "No current data":
        if spo2.get("color") == "green": score += 2
        elif spo2.get("color") == "red":
            score -= 5; signals.append((2, "SpO2 below usual level"))

    score = max(0, min(100, round(score)))
    signals.sort(key=lambda x: x[0], reverse=True)
    if signals:
        reason = " · ".join(text for _, text in signals[:3])
    elif form_zone == "green" and fatigue_zone == "green":
        reason = "Load balance and recovery signals are supportive."
    else:
        reason = "Recovery signals are broadly stable."

    if score >= 70: return score, "Race Ready", "green", reason
    if score <= 40: return score, "Recovery Bias", "red", reason
    return score, "Train Smart", "grey", reason

def compute_metrics(wellness, form_thresholds=None, fatigue_thresholds=None, baseline_wellness=None):
    sorted_wellness = sorted(wellness, key=lambda w: w.get("id", ""))
    latest = sorted_wellness[-1] if sorted_wellness else {}

    ctl = latest.get("ctl")
    atl = latest.get("atl")
    sleep_quality = latest.get("sleepQuality")
    sleep_quality_label, sleep_quality_text, sleep_quality_class = sleep_quality_details(sleep_quality)
    latest_sleep_score = latest.get("sleepScore")
    latest_sleep_secs = latest.get("sleepSecs")
    latest_sleep_hours = latest_sleep_secs / 3600.0 if isinstance(latest_sleep_secs, (int, float)) else None
    latest_sleep_duration = _fmt_hours(latest_sleep_hours) if latest_sleep_hours is not None else "n/a"
    latest_sleeping_hr = latest.get("avgSleepingHR")
    tsb = round(ctl - atl, 1) if (ctl is not None and atl is not None) else None

    sleep_values = [w["sleepSecs"] / 3600 for w in wellness if w.get("sleepSecs")]
    avg_sleep = round(statistics.mean(sleep_values), 1) if sleep_values else None

    weight_entries = [w for w in sorted_wellness if w.get("weight")]
    latest_weight = weight_entries[-1]["weight"] if weight_entries else None

    readiness_entries = [w for w in sorted_wellness if w.get("readiness") is not None]
    latest_readiness = readiness_entries[-1]["readiness"] if readiness_entries else None

    spo2_entries = [w for w in sorted_wellness if w.get("spO2") is not None]
    latest_spo2 = spo2_entries[-1]["spO2"] if spo2_entries else None

    form_zone = classify_form(tsb, form_thresholds)
    fatigue_zone = classify_fatigue(atl, ctl, fatigue_thresholds)
    personal_baselines = compute_personal_baselines(baseline_wellness or wellness)
    race_score, race_label, race_zone, race_reason = compute_race_readiness(
        form_zone, fatigue_zone, sleep_quality, personal_baselines
    )

    adaptive_sleep = personal_baselines.get("adaptive_sleep") or {}
    sleep_delta_min = adaptive_sleep.get("current_delta_min")
    sleep_reference_delta_min = adaptive_sleep.get("reference_delta_min")
    sleep_score_delta = round(latest_sleep_score - GARMIN_BASELINES["sleep_score"]) if isinstance(latest_sleep_score, (int, float)) else None
    spo2_delta = round(latest_spo2 - GARMIN_BASELINES["spo2"], 1) if isinstance(latest_spo2, (int, float)) else None

    return {
        "ctl": round(ctl, 1) if ctl is not None else "n/a",
        "atl": round(atl, 1) if atl is not None else "n/a",
        "tsb": tsb if tsb is not None else "n/a",
        "fitness_zone": classify_fitness_trend(wellness),
        "fatigue_zone": fatigue_zone,
        "form_zone": form_zone,
        "latest_rhr": latest.get("restingHR", "n/a"),
        "latest_hrv": latest.get("hrv", "n/a"),
        "avg_sleep": f"{avg_sleep}h" if avg_sleep is not None else "n/a",
        "avg_sleep_hours": avg_sleep,
        "latest_sleep_hours": round(latest_sleep_hours, 2) if latest_sleep_hours is not None else None,
        "latest_weight": f"{round(latest_weight, 1)}kg" if latest_weight is not None else "n/a",
        "latest_readiness": round(latest_readiness) if latest_readiness is not None else None,
        "latest_spo2": round(latest_spo2, 1) if latest_spo2 is not None else None,
        "sleep_quality": sleep_quality,
        "sleep_quality_label": sleep_quality_label,
        "sleep_quality_text": sleep_quality_text,
        "sleep_quality_class": sleep_quality_class,
        "latest_sleep_score": round(latest_sleep_score) if latest_sleep_score is not None else None,
        "latest_sleep_duration": latest_sleep_duration,
        "latest_sleeping_hr": round(latest_sleeping_hr) if latest_sleeping_hr is not None else None,
        "sleep_delta_min": sleep_delta_min,
        "sleep_reference_delta_min": sleep_reference_delta_min,
        "sleep_score_delta": sleep_score_delta,
        "spo2_delta": spo2_delta,
        "personal_baselines": personal_baselines,
        "adaptive_sleep": adaptive_sleep,
        "race_readiness_score": race_score,
        "race_readiness_label": race_label,
        "race_readiness_zone": race_zone,
        "race_readiness_css_color": {"green": "green", "red": "red", "grey": "grey-zone"}.get(race_zone, "grey-zone"),
        "race_readiness_reason": race_reason,
    }

def build_data_text(recent_activities, wellness, season_stats, notes=None, feelings=None, best_watts=None, vo2_trend=None):
    lines = ["RECENT ACTIVITIES (last {} days):".format(DAYS_BACK)]
    if not recent_activities:
        lines.append("(no activities found on Intervals.icu for this period)")
    for a in recent_activities:
        duration_sec = a.get("moving_time") or a.get("elapsed_time") or 0
        power = a.get("icu_weighted_avg_watts") or a.get("average_watts") or "n/a"
        lines.append(
            "- {date} | {name} | {type} | {dur} min | load {load} | "
            "power {pwr} | HR {hr} | calories {cal} | Intervals CHO used {cho_used}g | CHO ingested {cho_in}g".format(
                date=a.get("start_date_local", "").replace("T", " ")[:16],
                name=a.get("name", ""),
                type=a.get("type", ""),
                dur=round(duration_sec / 60),
                load=a.get("icu_training_load", "n/a"),
                pwr=power,
                hr=a.get("average_heartrate", "n/a"),
                cal=a.get("calories", "n/a"),
                cho_used=a.get("carbs_used", "n/a"),
                cho_in=a.get("carbs_ingested", "n/a"),
            )
        )

    lines.append("\nSEASON SUMMARY (last {} days, time-in-zone based):".format(SEASON_DAYS_BACK))
    lines.append(
        "- Total training time: {}h | Total load: {} | "
        "Low intensity: {}% | Moderate intensity: {}% | High intensity: {}%".format(
            season_stats["season_hours"], season_stats["season_total_load"],
            season_stats["zone_low_pct"], season_stats["zone_mod_pct"], season_stats["zone_high_pct"],
        )
    )

    if best_watts:
        lines.append("\nREAL POWER CURVE (actual best efforts, last 42 days - use these as the "
                     "ceiling for any power target you prescribe, never exceed them for that "
                     "duration or shorter):")
        for p in best_watts:
            lines.append("- {}: {}W".format(p["label"], p["watts"]))

    if vo2_trend and vo2_trend.get("available"):
        lines.append("\nVO2MAX TREND (MODEL ESTIMATES ONLY - longitudinal context, NOT a measured VO2max and NOT a primary readiness signal):")
        if vo2_trend.get("wearable_current") is not None:
            lines.append("- Wearable / Intervals Wellness: {} ml/kg/min | 28d delta {}".format(
                vo2_trend.get("wearable_current"), vo2_trend.get("wearable_delta28") if vo2_trend.get("wearable_delta28") is not None else "n/a"))
        if vo2_trend.get("performance_current") is not None:
            lines.append("- Intervals 5-min-power estimate: {} ml/kg/min | 28d delta {}".format(
                vo2_trend.get("performance_current"), vo2_trend.get("performance_delta28") if vo2_trend.get("performance_delta28") is not None else "n/a"))
        lines.append("- Trend agreement: {}. Use only as longitudinal performance context; do not let it override health, recovery, availability or recent training.".format(vo2_trend.get("agreement", "n/a")))

    lines.append("\nWELLNESS (last {} days):".format(DAYS_BACK))
    for w in sorted(wellness, key=lambda x: x.get("id", "")):
        line = (
            "- {date} | RHR {rhr} | HRV {hrv} | sleep {sleep}h | CTL {ctl} | ATL {atl}".format(
                date=w.get("id", ""),
                rhr=w.get("restingHR", "n/a"),
                hrv=w.get("hrv", "n/a"),
                sleep=round(w["sleepSecs"] / 3600, 1) if w.get("sleepSecs") else "n/a",
                ctl=round(w["ctl"], 1) if w.get("ctl") is not None else "n/a",
                atl=round(w["atl"], 1) if w.get("atl") is not None else "n/a",
            )
            + " | sleepQ {} | sleepScore {} | sleepingHR {} | SpO2 {} | wearableReadiness {}".format(
                ("Q" + str(w.get("sleepQuality"))) if w.get("sleepQuality") is not None else "n/a",
                round(w.get("sleepScore")) if w.get("sleepScore") is not None else "n/a",
                round(w.get("avgSleepingHR")) if w.get("avgSleepingHR") is not None else "n/a",
                round(w.get("spO2"), 1) if w.get("spO2") is not None else "n/a",
                round(w.get("readiness")) if w.get("readiness") is not None else "n/a",
            )
        )
        if w.get("weight"):
            line += " | weight {}kg".format(round(w["weight"], 1))
        if w.get("comments"):
            line += " | note: {}".format(w["comments"])
        lines.append(line)

    if notes:
        lines.append("\nCOACH NOTES (things the athlete has told you before, most recent last):")
        for n in notes:
            lines.append("- {date}: {text}".format(date=n.get("date", ""), text=n.get("text", "")))

    if feelings:
        lines.append("\nSELF-REPORTED DAILY LOG (1=bad, 10=amazing; context matters):")
        for f in feelings[-20:]:
            lines.append(
                "- {date} {time} | {value}/10 | {phase} | status {status} | sessions {sessions} | load {load} | note {note}".format(
                    date=f.get("date", ""), time=f.get("time", ""), value=f.get("value", ""), phase=f.get("phase", ""),
                    status=f.get("status", "NORMAL"), sessions=f.get("sessions", "n/a"), load=f.get("load", "n/a"), note=f.get("note") or "none"
                )
            )

    return "\n".join(lines)



def get_rome_now():
    """Current wall-clock time for the athlete/coach, independent of Render's server timezone."""
    return datetime.now(ROME_TZ)


def parse_local_activity_datetime(value):
    if not value:
        return None
    try:
        return datetime.fromisoformat(str(value).replace("Z", "+00:00")).replace(tzinfo=None)
    except (ValueError, TypeError):
        return None


def get_clock_preview(now=None):
    now = now or get_rome_now()
    hour = now.hour
    if hour < 12:
        phase = "Morning window · before 12:00 PM"
    elif hour < 17:
        phase = "Between sessions · 12:00 PM–05:00 PM"
    else:
        phase = "Evening window · after 05:00 PM"
    return {"time": now.strftime("%I:%M %p"), "time_clock": now.strftime("%I:%M"), "time_period": now.strftime("%p"), "phase": phase}


def build_coach_clock(recent_activities, now=None, planning_context=None):
    """Deterministic session awareness with health, events and V24 planned training.

    Intervals activities determine what is already done. Structured planning
    items determine what is allowed and what the athlete has committed to do.
    Blackout dates are removed before the AI sees a slot; races and planned
    training occupy their own slot; no-intensity always wins over planned demand.
    """
    now = now or get_rome_now()
    planning_context = planning_context or build_planning_context(now)
    today = now.date()
    today_iso = today.isoformat()
    today_acts = []
    for activity in recent_activities:
        start_raw = activity.get("start_date_local") or ""
        if start_raw[:10] != today_iso:
            continue
        dt = parse_local_activity_datetime(start_raw)
        hour = dt.hour if dt else None
        today_acts.append({
            "name": activity.get("name") or activity.get("type") or "Activity",
            "hour": hour,
            "time": dt.strftime("%I:%M %p") if dt else "time n/a",
        })

    am_done = any(a["hour"] is not None and a["hour"] < 12 for a in today_acts)
    pm_done = any(a["hour"] is not None and a["hour"] >= 17 for a in today_acts)
    blocked_today = today_iso in set(planning_context.get("blackout_dates") or [])
    no_intensity_today = today_iso in set(planning_context.get("no_intensity_dates") or [])
    health = planning_context.get("health_override")

    if health:
        phase = "HEALTH OVERRIDE"
        headline = "Health context has priority"
        explanation = (
            f'{health.get("kind")} is active through {health.get("until")}. '
            "THE LAB will not treat falling training load as tapering/peaking and will only expose slots compatible with the active restriction."
        )
    elif blocked_today:
        phase = "NO TRAINING"
        headline = "Today is blocked from training"
        explanation = "A structured availability rule removes today from Upcoming Sessions before the coach is called."
    elif no_intensity_today:
        phase = "RESTRICTED"
        headline = "No-intensity restriction active"
        explanation = "Today remains trainable, but Python will enforce easy aerobic work only even if the AI suggests intensity."
    elif now.hour < 12:
        phase = "AM WINDOW"
        headline = "Morning session decision"
        explanation = "THE LAB is anchored to the real activity log, today's constraints and the next open decision window."
    elif now.hour < 17:
        phase = "BETWEEN SESSIONS"
        headline = "Morning checked · evening next"
        explanation = "The morning window has passed. THE LAB checks the real activity log, then plans from the evening slot onward."
    else:
        if pm_done:
            phase = "DAY COMPLETE"
            headline = "Today's two-a-day is closed"
            explanation = "The evening activity is already logged, so planning moves forward rather than repeating today's work."
        else:
            phase = "PM WINDOW"
            headline = "Evening session decision"
            explanation = "It is after 05:00 PM. If no PM activity is logged, the current evening slot is the next decision."

    if now.hour < 12:
        am_status = "DONE" if am_done else ("BLOCKED" if blocked_today else "OPEN")
        am_class = "done" if am_done else ("missed" if blocked_today else "open")
        pm_status = "DONE" if pm_done else ("BLOCKED" if blocked_today else ("EASY ONLY" if no_intensity_today else "UPCOMING"))
        pm_class = "done" if pm_done else ("missed" if blocked_today else "upcoming")
    elif now.hour < 17:
        am_status = "DONE" if am_done else ("BLOCKED" if blocked_today else "NO ACTIVITY")
        am_class = "done" if am_done else "missed"
        pm_status = "DONE" if pm_done else ("BLOCKED" if blocked_today else ("EASY ONLY" if no_intensity_today else "UPCOMING"))
        pm_class = "done" if pm_done else ("missed" if blocked_today else "upcoming")
    else:
        am_status = "DONE" if am_done else ("BLOCKED" if blocked_today else "NO ACTIVITY")
        am_class = "done" if am_done else "missed"
        pm_status = "DONE" if pm_done else ("BLOCKED" if blocked_today else ("EASY ONLY" if no_intensity_today else "OPEN"))
        pm_class = "done" if pm_done else ("missed" if blocked_today else "open")

    blackout = set(planning_context.get("blackout_dates") or [])
    easy_only = set(planning_context.get("no_intensity_dates") or [])
    race_by_date = planning_context.get("race_by_date") or {}
    training_by_date = planning_context.get("training_by_date") or {}
    candidates = []
    race_added = set()
    training_added = set()

    def add_candidate(slot_date, period):
        ds = slot_date.isoformat()
        if ds in blackout:
            return

        race = race_by_date.get(ds)
        if race and ds not in easy_only:
            if ds not in race_added:
                candidates.append((slot_date, "RACE", race))
                race_added.add(ds)
            return

        planned = training_by_date.get(ds)
        if planned:
            # A day-level commitment occupies one decision slot and suppresses
            # duplicate theoretical AM/PM prescriptions for that date. If an
            # activity is already logged today, treat today's commitment as done.
            if ds in training_added:
                return
            training_added.add(ds)
            if slot_date == today and today_acts:
                return
            candidates.append((slot_date, "PLANNED", planned))
            return

        candidates.append((slot_date, period, None))

    if now.hour < 12 and not am_done:
        add_candidate(today, "AM")
    if not pm_done:
        add_candidate(today, "PM")

    d = today + timedelta(days=1)
    guard = 0
    while len(candidates) < 3 and guard < 120:
        add_candidate(d, "AM")
        if len(candidates) < 3:
            add_candidate(d, "PM")
        d += timedelta(days=1)
        guard += 1

    next_slots = []
    for slot_date, period, event in candidates[:3]:
        ds = slot_date.isoformat()
        if slot_date == today:
            day_word = "Today"
        elif slot_date == today + timedelta(days=1):
            day_word = "Tomorrow"
        else:
            day_word = slot_date.strftime("%A")

        training_environment = None
        training_demand = None
        event_note = None
        if period == "RACE":
            label = f'{day_word} · RACE · {event.get("title") or "Priority event"}'
            window = "priority event"
            restriction = "RACE"
        elif period == "PLANNED":
            training_environment = str(event.get("training_environment") or ATHLETE_FUELING_PROFILE["default_training_environment"]).upper()
            if training_environment not in ("INDOOR", "OUTDOOR"):
                training_environment = ATHLETE_FUELING_PROFILE["default_training_environment"]
            training_demand = str(event.get("training_demand") or "COACH").upper()
            if training_demand not in ("EASY", "NORMAL", "HARD", "COACH"):
                training_demand = "COACH"
            label = f'{day_word} · PLANNED · {training_environment} · {event.get("title") or "Training"}'
            window = "athlete-planned"
            restriction = "NO_INTENSITY" if ds in easy_only else "NONE"
            event_note = event.get("note") or ""
        else:
            window = "before 12:00 PM" if period == "AM" else "after 05:00 PM"
            label = f"{day_word} · {period} · {window}"
            restriction = "NO_INTENSITY" if ds in easy_only else "NONE"

        next_slots.append({
            "date": ds, "period": period, "window": window, "label": label,
            "restriction": restriction,
            "restriction_until": next((i.get("end_date") for i in planning_context.get("upcoming_items", []) if i.get("restriction_type") == restriction and _date_in_item(i, slot_date)), None) if restriction == "NO_INTENSITY" else None,
            "is_race": period == "RACE",
            "is_planned_training": period == "PLANNED",
            "event_title": event.get("title") if event else None,
            "event_note": event_note,
            "training_environment": training_environment,
            "training_demand": training_demand,
            "planning_item_id": event.get("id") if event and period == "PLANNED" else None,
        })

    acts_text = ", ".join(f'{a["time"]} {a["name"]}' for a in today_acts)
    minutes = now.hour * 60 + now.minute
    day_progress = round(minutes / 1440 * 100, 1)
    clock_angle = (day_progress / 100.0) * 2 * math.pi - (math.pi / 2)
    return {
        "iso": now.isoformat(), "time": now.strftime("%I:%M %p"), "time_clock": now.strftime("%I:%M"), "time_period": now.strftime("%p"), "timezone": now.tzname() or "Europe/Rome",
        "date_label": now.strftime("%d/%m/%Y"), "phase": phase, "headline": headline, "explanation": explanation,
        "am_done": am_done, "pm_done": pm_done, "am_status": am_status, "pm_status": pm_status,
        "am_status_class": am_class, "pm_status_class": pm_class, "today_activity_count": len(today_acts),
        "today_activities_text": acts_text, "next_slots": next_slots,
        "next_slot_label": next_slots[0]["label"] if next_slots else "No available training slot",
        "day_progress": day_progress,
        "marker_x": round(90 + 68 * math.cos(clock_angle), 1),
        "marker_y": round(90 + 68 * math.sin(clock_angle), 1),
        "planning_summary": planning_context.get("summary", "Training as planned"),
    }



def coach_clock_text(clock):
    slot_lines = []
    for i, slot in enumerate(clock.get("next_slots") or []):
        extras = []
        if slot.get("is_planned_training"):
            extras.append(f'environment {slot.get("training_environment") or "n/a"}')
            extras.append(f'expected demand {slot.get("training_demand") or "COACH"}')
            if slot.get("event_note"):
                extras.append(f'note {slot.get("event_note")}')
        extra = " | " + " | ".join(extras) if extras else ""
        slot_lines.append(f'{i+1}. {slot["label"]} ({slot["date"]}) | restriction {slot.get("restriction", "NONE")}{extra}')
    slots = "\n".join(slot_lines)
    activities = clock.get("today_activities_text") or "none logged yet"
    return (
        "COACH CLOCK (authoritative timing context):\n"
        f'- Snapshot requested at {clock["time"]} {clock["timezone"]} on {clock["date_label"]}.\n'
        f'- Current phase: {clock["phase"]}.\n'
        f'- Planning state: {clock.get("planning_summary", "Training as planned")}.\n'
        f'- Morning slot status: {clock["am_status"]}. Evening slot status: {clock["pm_status"]}.\n'
        f'- Activities already logged today: {activities}.\n'
        "- The next three VALID decision slots after hard Python filtering are:\n"
        f"{slots}\n"
        "Never prescribe a removed/blocked slot. NO_INTENSITY means easy aerobic/recovery only. RACE means the event itself, not an extra workout. PLANNED means an athlete-created training commitment: keep its structured environment and use expected demand as planning guidance."
    )




def classify_training_family(activity):
    """Classify a completed activity into a coaching family using its title first,
    then time-in-zone as a conservative fallback. This is intentionally broad: the
    goal is to stop Claude from accidentally repeating the same quality stimulus,
    not to pretend we can perfectly reverse-engineer every Zwift workout."""
    name = str(activity.get("name") or "").lower()
    compact = name.replace("-", " ").replace("_", " ")

    keyword_groups = [
        ("Recovery", ("recovery", "recuper", "easy spin", "scarico")),
        ("Sprint / Neuromuscular", ("sprint", "neuromus", "anaerobic", "anaerobico")),
        ("VO2max", ("vo2", "vo₂", "vo 2", "max aerobic")),
        ("Over-Under", ("over under", "overunder", "o&u", "over / under")),
        ("Threshold / TTE", ("tte", "threshold", "soglia", "ftp", "time to exhaustion")),
        ("Sweet Spot", ("sweet spot", "sweetspot")),
        ("Tempo", ("tempo", "z3", "zone 3")),
        ("Endurance / Z2", ("z2", "zone 2", "endurance", "aerobic", "endurance ride")),
    ]
    for label, keys in keyword_groups:
        if any(k in compact for k in keys):
            return label

    zone_times = activity.get("icu_zone_times") or []
    if zone_times:
        try:
            secs = [float(z.get("secs") or 0) for z in zone_times]
            low, mod, high = bucket_zone_seconds(secs)
            total = low + mod + high
            if total > 0:
                high_pct = 100 * high / total
                mod_pct = 100 * mod / total
                if high_pct >= 15:
                    return "High Intensity / Mixed"
                if mod_pct >= 30:
                    return "Tempo / Threshold Mixed"
                if low / total >= 0.75:
                    return "Endurance / Z2"
        except (TypeError, ValueError):
            pass
    return "Other / Mixed"


def is_hard_training_family(family):
    f = (family or "").lower()
    return any(k in f for k in (
        "vo2", "threshold", "tte", "over-under", "sprint", "neuromuscular",
        "high intensity", "tempo / threshold"
    ))


def _num(value):
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _zone_secs(value):
    if not value:
        return []
    out = []
    for z in value:
        if isinstance(z, dict):
            out.append(int(z.get("secs") or 0))
        else:
            try:
                out.append(int(z or 0))
            except (TypeError, ValueError):
                out.append(0)
    return out


def fetch_activity_detail(activity_id):
    """Fetch Intervals' analysed intervals for one completed activity.

    Single-activity fallback used if the batch endpoint is unavailable. Failure
    degrades to summary data instead of breaking the whole Snapshot.
    """
    if not activity_id:
        return None
    url = f"https://intervals.icu/api/v1/activity/{activity_id}?intervals=true"
    try:
        r = requests.get(url, headers=get_intervals_headers(), timeout=20)
        r.raise_for_status()
        return r.json()
    except Exception:
        return None


def fetch_activity_details(activity_ids):
    """Fetch up to a few activity details in one Intervals request.

    Intervals supports a comma-separated activity detail endpoint with
    intervals=true. A parallel single-activity fallback keeps the Snapshot
    resilient if that endpoint ever rejects a request.
    """
    ids = [str(x) for x in activity_ids if x]
    if not ids:
        return {}
    url = (
        f"https://intervals.icu/api/v1/athlete/{ICU_ATHLETE_ID}/activities/"
        f"{','.join(ids)}?intervals=true"
    )
    try:
        r = requests.get(url, headers=get_intervals_headers(), timeout=25)
        r.raise_for_status()
        payload = r.json()
        if isinstance(payload, list):
            found = {str(x.get("id")): x for x in payload if isinstance(x, dict) and x.get("id")}
            if found:
                return found
    except Exception:
        pass

    found = {}
    with ThreadPoolExecutor(max_workers=min(3, len(ids))) as pool:
        futures = {pool.submit(fetch_activity_detail, activity_id): activity_id for activity_id in ids}
        for future in as_completed(futures):
            activity_id = futures[future]
            try:
                detail = future.result()
            except Exception:
                detail = None
            if isinstance(detail, dict):
                found[str(activity_id)] = detail
    return found


def _interval_line(interval):
    secs = int(interval.get("moving_time") or interval.get("elapsed_time") or 0)
    if secs < 45:
        return None
    mins = secs / 60.0
    dur = f"{round(mins)}m" if mins >= 2 else f"{secs}s"
    watts = _num(interval.get("average_watts"))
    hr = _num(interval.get("average_heartrate"))
    zone = interval.get("zone")
    bits = [dur]
    if watts is not None:
        bits.append(f"{round(watts)} W")
    if hr is not None:
        bits.append(f"HR {round(hr)}")
    if zone is not None:
        bits.append(f"Z{zone}")
    return " · ".join(bits)


def _zone_summary(zone_secs):
    parts = []
    for idx, secs in enumerate(zone_secs or [], start=1):
        secs = int(secs or 0)
        if secs <= 0:
            continue
        if secs >= 60:
            parts.append(f"Z{idx} {round(secs / 60)}m")
        else:
            parts.append(f"Z{idx} {secs}s")
    return " · ".join(parts[:7])


def _is_heat_name(name):
    return bool(re.search(r"\bHEAT\b", str(name or ""), flags=re.IGNORECASE))


def build_previous_training_blocks(recent_activities, limit=3):
    """Most recent completed activities enriched with Intervals interval detail."""
    now = get_rome_now().replace(tzinfo=None)
    candidates = []
    for a in recent_activities or []:
        dt = parse_local_activity_datetime(a.get("start_date_local") or "")
        if dt and dt <= now:
            candidates.append((dt, a))
    candidates.sort(key=lambda x: x[0], reverse=True)
    candidates = candidates[:limit]
    details = fetch_activity_details([a.get("id") for _, a in candidates])

    blocks = []
    for dt, summary in candidates:
        detail = details.get(str(summary.get("id"))) or summary
        name = detail.get("name") or summary.get("name") or "Activity"
        is_heat = _is_heat_name(name)
        intervals = detail.get("icu_intervals") or []
        work = []
        for it in intervals:
            # Intervals currently documents WORK and RECOVERY interval types.
            if str(it.get("type") or "WORK").upper() != "WORK":
                continue
            line = _interval_line(it)
            if line:
                work.append(line)
        if not work:
            for it in intervals:
                line = _interval_line(it)
                if line:
                    work.append(line)
        work = work[:6]

        pz = _zone_secs(detail.get("icu_zone_times") or summary.get("icu_zone_times"))
        hz = _zone_secs(detail.get("icu_hr_zone_times") or summary.get("icu_hr_zone_times"))
        dec = _num(detail.get("decoupling") if detail.get("decoupling") is not None else summary.get("decoupling"))
        family = classify_training_family(detail)
        avg_w = _num(detail.get("average_watts") or summary.get("average_watts"))
        avg_hr = _num(detail.get("average_heartrate") or summary.get("average_heartrate"))
        ftp = detail.get("icu_ftp") or summary.get("icu_ftp")
        pz_text = _zone_summary(pz)
        hz_text = _zone_summary(hz)

        if is_heat:
            if dec is not None and dec >= 5:
                consideration = "🔥 HEAT signature · meaningful cardiovascular drift. Treat the mechanical load and thermal/autonomic strain as separate stressors."
            else:
                consideration = "🔥 HEAT signature · interpret average watts cautiously: thermal strain can raise cardiovascular cost without raising mechanical output."
        elif is_hard_training_family(family):
            consideration = "⚡ Quality stimulus · include this in hard-session spacing before prescribing the next intensity block."
        else:
            consideration = "🫀 Aerobic context · use zone distribution and HR response, not average power alone, when judging recovery cost."

        blocks.append({
            "date": dt.date().isoformat(), "time": dt.strftime("%I:%M %p"), "name": name,
            "heat": is_heat, "family": family,
            "duration_min": round((detail.get("moving_time") or summary.get("moving_time") or 0) / 60),
            "load": detail.get("icu_training_load", summary.get("icu_training_load")),
            "avg_watts": round(avg_w) if avg_w is not None else None,
            "avg_hr": round(avg_hr) if avg_hr is not None else None,
            "decoupling": round(dec, 1) if dec is not None else None,
            "ftp": ftp, "power_zones": pz, "hr_zones": hz,
            "power_zone_summary": pz_text, "hr_zone_summary": hz_text,
            "intervals": work, "consideration": consideration,
        })
    return blocks

def previous_training_blocks_text(blocks):
    if not blocks:
        return "PREVIOUS TRAINING BLOCKS:\n- No completed activity detail available."
    lines = ["PREVIOUS TRAINING BLOCKS (Intervals.icu analysed detail — use these before interpreting recovery):"]
    for b in blocks:
        tag = "HEAT" if b.get("heat") else b.get("family")
        lines.append(
            f'- {b["date"]} {b["time"]} | {tag} | {b["name"]} | {b["duration_min"]} min | '
            f'load {b.get("load")} | avg {b.get("avg_watts") or "n/a"} W / HR {b.get("avg_hr") or "n/a"} | '
            f'decoupling {b.get("decoupling") if b.get("decoupling") is not None else "n/a"}% | FTP {b.get("ftp") or "n/a"} W'
        )
        if b.get("power_zone_summary"):
            lines.append("  Power zones: " + b["power_zone_summary"])
        if b.get("hr_zone_summary"):
            lines.append("  HR zones: " + b["hr_zone_summary"])
        if b.get("intervals"):
            lines.append("  Intervals: " + " ; ".join(b["intervals"]))
        lines.append("  Interpretation cue: " + b["consideration"])
    return "\n".join(lines)


def _daily_training_map(activities):
    days = {}
    for a in activities or []:
        ds = str(a.get("start_date_local") or "")[:10]
        if not ds:
            continue
        d = days.setdefault(ds, {"load": 0.0, "heat": False, "names": []})
        d["load"] += _num(a.get("icu_training_load")) or 0.0
        name = a.get("name") or ""
        d["names"].append(name)
        if _is_heat_name(name):
            d["heat"] = True
    return days

def build_heat_response_pattern(season_activities, season_wellness):
    """Detect repeated next-morning HRV behaviour after named HEAT sessions.

    Each next-morning HRV is compared with the median of the preceding seven
    available HRV readings. Non-HEAT controls are load-matched when there are
    enough candidates; otherwise THE LAB labels the comparator as broad rather
    than pretending equivalence. This is association detection, not causality.
    """
    wellness = {str(w.get("id")): w for w in season_wellness or [] if w.get("id")}
    days = _daily_training_map(season_activities)
    samples, controls = [], []

    for ds, info in sorted(days.items()):
        try:
            d = date.fromisoformat(ds)
        except ValueError:
            continue
        next_ds = (d + timedelta(days=1)).isoformat()
        next_hrv = _num((wellness.get(next_ds) or {}).get("hrv"))
        if next_hrv is None:
            continue
        prior = []
        for back in range(1, 8):
            v = _num((wellness.get((d - timedelta(days=back)).isoformat()) or {}).get("hrv"))
            if v is not None:
                prior.append(v)
        if len(prior) < 3:
            continue
        baseline = statistics.median(prior)
        delta_pct = (next_hrv - baseline) / baseline * 100.0 if baseline else 0.0
        rec = {
            "date": ds, "next_date": next_ds, "hrv": next_hrv, "baseline": baseline,
            "delta_pct": delta_pct, "load": info["load"],
        }
        (samples if info["heat"] else controls).append(rec)

    # Prefer one unique non-HEAT control of broadly similar load per HEAT day.
    matched_controls = []
    used_control_dates = set()
    for sample in samples:
        tol = max(15.0, abs(sample["load"]) * 0.35)
        eligible = [
            c for c in controls
            if c["date"] not in used_control_dates and abs(c["load"] - sample["load"]) <= tol
        ]
        if eligible:
            chosen = min(eligible, key=lambda c: abs(c["load"] - sample["load"]))
            matched_controls.append(chosen)
            used_control_dates.add(chosen["date"])

    if len(matched_controls) >= 3:
        comparator_pool = matched_controls
        comparator_mode = "LOAD-MATCHED"
    else:
        comparator_pool = controls
        comparator_mode = "BROAD"

    neg = [x for x in samples if x["delta_pct"] < -3.0]
    n = len(samples)
    median_delta = statistics.median([x["delta_pct"] for x in samples]) if samples else None
    control_delta = statistics.median([x["delta_pct"] for x in comparator_pool]) if comparator_pool else None
    consistency = len(neg) / n if n else 0.0
    if n < 3:
        confidence = "INSUFFICIENT DATA"
    elif n >= 8 and consistency >= .70:
        confidence = "STRONG"
    elif n >= 5 and consistency >= .60:
        confidence = "MODERATE"
    else:
        confidence = "WEAK"

    if median_delta is None:
        headline = "Not enough paired HEAT → next-morning HRV observations yet."
    else:
        direction = "lower" if median_delta < 0 else "higher"
        headline = (
            f"Next-morning HRV has been {direction} by a median {abs(median_delta):.1f}% "
            "versus the preceding 7-day median after analysed HEAT days."
        )

    comparator = None
    if control_delta is not None and len(comparator_pool) >= 3:
        if comparator_mode == "LOAD-MATCHED":
            comparator = (
                f"Load-matched non-HEAT comparator: {control_delta:+.1f}% median next-morning "
                f"HRV deviation ({len(comparator_pool)} matched days)."
            )
        else:
            comparator = (
                f"Broad non-HEAT comparator: {control_delta:+.1f}% median next-morning HRV "
                f"deviation ({len(comparator_pool)} days); too few load-matched controls for a cleaner comparison."
            )

    # Use the most recent wellness day that actually contains HRV, not merely
    # the newest wellness row (which can exist before overnight HRV is populated).
    hrv_dates = sorted(ds for ds, w in wellness.items() if _num(w.get("hrv")) is not None)
    latest_w = hrv_dates[-1] if hrv_dates else None
    latest_hrv = _num((wellness.get(latest_w) or {}).get("hrv")) if latest_w else None
    previous_day = (date.fromisoformat(latest_w) - timedelta(days=1)).isoformat() if latest_w else None
    current_heat = bool(previous_day and (days.get(previous_day) or {}).get("heat"))
    current_relevance = bool(
        current_heat and latest_hrv is not None and latest_hrv < GARMIN_BASELINES["hrv_low"]
    )

    return {
        "available": n > 0, "confidence": confidence,
        "confidence_class": confidence.lower().replace(" ", "-"),
        "samples": n, "negative_count": len(neg), "consistency_pct": round(consistency * 100),
        "median_delta_pct": round(median_delta, 1) if median_delta is not None else None,
        "control_delta_pct": round(control_delta, 1) if control_delta is not None else None,
        "control_samples": len(comparator_pool), "control_mode": comparator_mode,
        "headline": headline, "comparator": comparator,
        "current_relevance": current_relevance,
        "confidence_note": (
            "repeated post-HEAT HRV suppression is well supported by your data." if confidence == "STRONG" else
            "a meaningful signal is present, but the evidence is not fully robust yet." if confidence == "MODERATE" else
            "a possible personal pattern is emerging, but the evidence is still limited or inconsistent." if confidence == "WEAK" else
            "there are too few paired HEAT observations to draw a usable conclusion yet."
        ),
        "current_note": (
            "THE LAB reads the latest below-baseline HRV as compatible with your recurring post-HEAT pattern and cross-checks it against resting HR, sleep and subjective status."
            if current_relevance else None
        ),
    }

def heat_response_pattern_text(pattern):
    if not pattern or not pattern.get("available"):
        return "PERSONAL HEAT RESPONSE PATTERN:\n- Insufficient paired HEAT → next-morning HRV data. Do not infer a relationship yet."
    lines = ["PERSONAL HEAT RESPONSE PATTERN (Python association detector; correlation is not causation):",
             f'- Confidence: {pattern["confidence"]} | paired HEAT days {pattern["samples"]} | HRV >3% below prior 7-day median on {pattern["negative_count"]}/{pattern["samples"]} ({pattern["consistency_pct"]}%).',
             f'- Confidence meaning: {pattern.get("confidence_note", "n/a")}',
             '- ' + pattern["headline"]]
    if pattern.get("comparator"):
        lines.append('- ' + pattern["comparator"])
    if pattern.get("current_note"):
        lines.append('- CURRENT CONTEXT: ' + pattern["current_note"])
    lines.append('- Coaching rule: use this as an explanation/context signal only. Do not dismiss low HRV when RHR, sleep, subjective status or performance also deteriorate.')
    return "\n".join(lines)



def build_aerobic_efficiency(season_activities, now=None):
    """Track repeatable aerobic power/HR behaviour in comparable steady Z2 rides.

    HEAT sessions are deliberately excluded because their purpose is to increase
    cardiovascular strain. The ratio is a longitudinal context metric, not a
    laboratory measure of mechanical or metabolic efficiency. Intervals' own
    decoupling value is retained alongside it as the durability signal.
    """
    now = now or get_rome_now()
    today = now.date()
    candidates = []
    for a in season_activities or []:
        if classify_training_family(a) != "Endurance / Z2" or _is_heat_name(a.get("name")):
            continue
        secs = a.get("moving_time") or a.get("elapsed_time") or 0
        if not isinstance(secs, (int, float)) or secs < 2400:
            continue
        try:
            watts = float(a.get("average_watts"))
            hr = float(a.get("average_heartrate"))
        except (TypeError, ValueError):
            continue
        if not (80 <= watts <= 500 and 80 <= hr <= 210):
            continue
        vi = a.get("icu_variability_index")
        try:
            vi = float(vi) if vi is not None else None
        except (TypeError, ValueError):
            vi = None
        if vi is not None and vi > 1.12:
            continue
        raw = str(a.get("start_date_local") or "")[:10]
        try:
            d = date.fromisoformat(raw)
        except Exception:
            continue
        trainer = a.get("trainer") is True or str(a.get("trainer") or "").lower() == "true"
        dec = a.get("decoupling")
        try:
            dec = float(dec) if dec is not None else None
        except (TypeError, ValueError):
            dec = None
        if dec is not None and abs(dec) > 40:
            dec = None
        candidates.append({
            "date": d, "date_iso": raw, "environment": "INDOOR" if trainer else "OUTDOOR",
            "watts": watts, "hr": hr, "ratio": watts / hr, "decoupling": dec,
            "duration_min": round(float(secs) / 60.0), "name": a.get("name") or "Endurance / Z2",
        })

    recent_start = today - timedelta(days=13)
    prior_start = today - timedelta(days=41)
    prior_end = today - timedelta(days=14)

    def split(items):
        recent = [x for x in items if recent_start <= x["date"] <= today]
        prior = [x for x in items if prior_start <= x["date"] <= prior_end]
        return recent, prior

    chosen_env = None
    selected = candidates
    viable = []
    for env in ("INDOOR", "OUTDOOR"):
        group = [x for x in candidates if x["environment"] == env]
        rec, old = split(group)
        if len(rec) >= 2 and len(old) >= 3:
            viable.append((len(rec) + len(old), env, group))
    if viable:
        _, chosen_env, selected = max(viable, key=lambda x: x[0])
    recent, prior = split(selected)

    result = {
        "available": len(recent) >= 2,
        "cohort": chosen_env or "MIXED",
        "cohort_label": f"{chosen_env.title()} steady Z2" if chosen_env else "Steady Z2 · mixed environment",
        "recent_samples": len(recent), "baseline_samples": len(prior),
        "recent_ratio": None, "baseline_ratio": None, "trend_pct": None,
        "recent_decoupling": None, "baseline_decoupling": None, "decoupling_change": None,
        "status": "LEARNING", "status_class": "grey", "confidence": "LOW",
        "headline": "More comparable steady Z2 sessions are needed before THE LAB calls a trend.",
        "latest_sessions": [],
        "note": "HEAT sessions are excluded so deliberate thermal cardiovascular strain does not contaminate the normal aerobic baseline.",
    }
    if recent:
        result["recent_ratio"] = round(statistics.median(x["ratio"] for x in recent), 3)
        recent_dec = [x["decoupling"] for x in recent if x.get("decoupling") is not None]
        if recent_dec:
            result["recent_decoupling"] = round(statistics.median(recent_dec), 1)
    if prior:
        result["baseline_ratio"] = round(statistics.median(x["ratio"] for x in prior), 3)
        prior_dec = [x["decoupling"] for x in prior if x.get("decoupling") is not None]
        if prior_dec:
            result["baseline_decoupling"] = round(statistics.median(prior_dec), 1)
    if result["recent_ratio"] is not None and result["baseline_ratio"]:
        result["trend_pct"] = round((result["recent_ratio"] / result["baseline_ratio"] - 1.0) * 100.0, 1)
    if result["recent_decoupling"] is not None and result["baseline_decoupling"] is not None:
        result["decoupling_change"] = round(result["recent_decoupling"] - result["baseline_decoupling"], 1)

    if len(recent) >= 3 and len(prior) >= 5:
        result["confidence"] = "HIGH"
    elif len(recent) >= 2 and len(prior) >= 3:
        result["confidence"] = "MODERATE"

    trend = result.get("trend_pct")
    recent_dec = result.get("recent_decoupling")
    old_dec = result.get("baseline_decoupling")
    if trend is not None:
        if recent_dec is not None and old_dec is not None and recent_dec >= old_dec + 2.0 and recent_dec >= 5.0:
            result["status"], result["status_class"] = "DURABILITY WATCH", "orange"
            result["headline"] = f"Power/HR ratio is {trend:+.1f}% vs the prior baseline, but aerobic decoupling has worsened by {recent_dec-old_dec:+.1f} pp."
        elif trend >= 1.5:
            result["status"], result["status_class"] = "IMPROVING", "green"
            result["headline"] = f"At comparable steady Z2, recent power per heartbeat is {trend:+.1f}% above the prior baseline."
        elif trend <= -2.5:
            result["status"], result["status_class"] = "BELOW RECENT NORM", "orange"
            result["headline"] = f"At comparable steady Z2, recent power per heartbeat is {trend:+.1f}% below the prior baseline."
        else:
            result["status"], result["status_class"] = "STABLE", "cyan"
            result["headline"] = f"Steady-Z2 power/HR ratio is stable ({trend:+.1f}% vs the prior baseline)."

    for x in sorted(selected, key=lambda z: z["date"], reverse=True)[:3]:
        result["latest_sessions"].append({
            "date": x["date_iso"], "watts": round(x["watts"]), "hr": round(x["hr"]),
            "ratio": round(x["ratio"], 3), "decoupling": round(x["decoupling"], 1) if x.get("decoupling") is not None else None,
            "duration_min": x["duration_min"], "environment": x["environment"],
        })
    return result


def _wellness_value_near(wellness, field, target_day, max_gap_days=4):
    best = None
    for w in wellness or []:
        value = w.get(field)
        if not isinstance(value, (int, float)):
            continue
        try:
            d = date.fromisoformat(str(w.get("id") or "")[:10])
        except Exception:
            continue
        gap = abs((d - target_day).days)
        if gap <= max_gap_days and (best is None or gap < best[0]):
            best = (gap, float(value))
    return best[1] if best else None


def build_training_state(season_activities, season_wellness, planning_context, metrics, feeling_trend=None, now=None):
    """Deterministic periodisation state built from load trend + calendar context.

    This is not an AI label and never infers tapering from illness/injury-driven
    loss of load. Health/restriction context has absolute priority.
    """
    now = now or get_rome_now()
    today = now.date()
    planning_context = planning_context or {}
    health = planning_context.get("health_override")
    next_race = planning_context.get("next_race") or {}

    def load_between(start_day, end_day):
        total = 0.0
        count = 0
        for a in season_activities or []:
            raw = str(a.get("start_date_local") or "")[:10]
            try:
                d = date.fromisoformat(raw)
            except Exception:
                continue
            if start_day <= d <= end_day:
                load = a.get("icu_training_load")
                if isinstance(load, (int, float)):
                    total += max(0.0, float(load))
                count += 1
        return total, count

    load7, sessions7 = load_between(today - timedelta(days=6), today)
    prior21, prior_sessions = load_between(today - timedelta(days=27), today - timedelta(days=7))
    prior_weekly = prior21 / 3.0 if prior21 > 0 else None
    load_ratio = load7 / prior_weekly if prior_weekly and prior_weekly > 0 else None

    latest_w = sorted(season_wellness or [], key=lambda x: str(x.get("id") or ""))[-1] if season_wellness else {}
    ctl_now = latest_w.get("ctl") if isinstance(latest_w.get("ctl"), (int, float)) else None
    atl_now = latest_w.get("atl") if isinstance(latest_w.get("atl"), (int, float)) else None
    ctl_28 = _wellness_value_near(season_wellness, "ctl", today - timedelta(days=28))
    ctl_delta_28 = round(ctl_now - ctl_28, 1) if ctl_now is not None and ctl_28 is not None else None
    ramp = latest_w.get("rampRate") if isinstance(latest_w.get("rampRate"), (int, float)) else None
    atl_ctl = atl_now / ctl_now if atl_now is not None and ctl_now and ctl_now > 0 else None

    pb = metrics.get("personal_baselines") or {}
    recovery_flags = []
    if (pb.get("hrv") or {}).get("color") == "red": recovery_flags.append("HRV below personal range")
    if (pb.get("rhr") or {}).get("color") == "red": recovery_flags.append("resting HR outside personal range")
    if (pb.get("sleep") or {}).get("color") in ("red", "orange"): recovery_flags.append("sleep below habitual opportunity")
    if (feeling_trend or {}).get("label") == "TRENDING DOWN": recovery_flags.append("subjective trend is falling")

    try:
        race_days = int(next_race.get("days_away")) if next_race and next_race.get("days_away") is not None else None
    except Exception:
        race_days = None

    if health:
        state, css, icon = "HEALTH HOLD", "red", "🛡️"
        headline = "Health/restriction context overrides periodisation labels."
        why = f"{health.get('kind', 'Health restriction')} is active through {health.get('until', 'the current restriction window')}; falling ATL or rising TSB is not treated as tapering or peaking."
    elif race_days is not None and race_days <= 2:
        state, css, icon = "RACE PREP", "green", "🏁"
        headline = "Preserve freshness and race specificity; there is no fitness to gain now."
        why = f"The priority race is {race_days} day(s) away. THE LAB prioritises readiness, fueling and low-cost activation over new training load."
    elif race_days is not None and 3 <= race_days <= 8:
        state, css, icon = "TAPER", "purple", "🎚️"
        headline = "Reduce accumulated fatigue while preserving the qualities already built."
        why = f"The priority race is {race_days} days away. This window is classified as taper even if a recent long ride temporarily keeps ATL high; health context would override this label if present."
    elif race_days is not None and 9 <= race_days <= 14:
        state, css, icon = "RACE PREP", "cyan", "🎯"
        headline = "Training is becoming race-specific while total fatigue must stay controlled."
        why = f"The priority race is {race_days} days away, so the final useful stimulus is balanced against the recovery time still available."
    elif len(recovery_flags) >= 2 or (atl_ctl is not None and atl_ctl >= 1.18) or (load_ratio is not None and load_ratio >= 1.35):
        state, css, icon = "RECOVERY", "orange", "♻️"
        headline = "Absorb the recent block before adding another dense stimulus."
        why = "Multiple load/recovery signals point to accumulated strain rather than a need to chase more training stress."
    elif (ctl_delta_28 is not None and ctl_delta_28 >= 1.5 and (load_ratio is None or load_ratio >= 0.95)) or (ramp is not None and ramp >= 0.5):
        state, css, icon = "BUILD", "cyan", "🏗️"
        headline = "Chronic load is progressing and the calendar still allows productive accumulation."
        why = "Recent load and CTL trajectory are consistent with a controlled build rather than maintenance or unloading."
    else:
        state, css, icon = "MAINTENANCE", "green", "⚖️"
        headline = "Hold fitness with purposeful work instead of forcing load progression."
        why = "Load and CTL are broadly stable, with no stronger race, recovery or health signal requiring another phase."

    signals = []
    if ctl_delta_28 is not None: signals.append(f"CTL 28d {ctl_delta_28:+.1f}")
    if ramp is not None: signals.append(f"Ramp {ramp:+.1f}")
    if prior_weekly is not None: signals.append(f"7d load {round(load7)} vs prior weekly {round(prior_weekly)}")
    if atl_ctl is not None: signals.append(f"ATL/CTL {atl_ctl:.2f}")
    if race_days is not None: signals.append(f"Race {race_days}d")
    if recovery_flags: signals.append(" · ".join(recovery_flags[:2]))

    wellness_count = sum(1 for w in season_wellness or [] if isinstance(w.get("ctl"), (int, float)))
    if wellness_count >= 28 and prior_sessions >= 4:
        confidence = "HIGH"
    elif wellness_count >= 14:
        confidence = "MODERATE"
    else:
        confidence = "LOW"
    return {
        "state": state, "state_class": css, "icon": icon, "confidence": confidence,
        "headline": headline, "why": why, "signals": signals[:5],
        "load_7d": round(load7), "prior_weekly_load": round(prior_weekly) if prior_weekly is not None else None,
        "load_ratio": round(load_ratio, 2) if load_ratio is not None else None,
        "ctl_delta_28": ctl_delta_28, "ramp_rate": round(ramp, 1) if ramp is not None else None,
        "atl_ctl": round(atl_ctl, 2) if atl_ctl is not None else None,
        "race_days": race_days,
    }


def build_physiological_state(metrics, training_state, aerobic_efficiency, metabolic_context, heat_pattern=None, feeling_trend=None):
    """Multi-signal state matrix; deliberately not collapsed into another 0–100 score."""
    pb = metrics.get("personal_baselines") or {}
    hrv = pb.get("hrv") or {}
    rhr = pb.get("rhr") or {}
    sleep = pb.get("sleep") or {}
    heat_current = bool((heat_pattern or {}).get("current_relevance"))

    if hrv.get("color") == "red" and rhr.get("color") == "red":
        autonomous = ("STRAINED", "red", "HRV is suppressed while resting HR is also outside the personal range.")
    elif hrv.get("color") == "red" and heat_current:
        autonomous = ("HEAT STRAIN", "orange", "Low HRV follows HEAT and matches the learned context; THE LAB still cross-checks resting HR and recovery.")
    elif hrv.get("color") == "red" or rhr.get("color") == "red":
        autonomous = ("WATCH", "orange", "One autonomic marker is outside the personal range while the other signals provide context.")
    elif hrv.get("color") == "green" and rhr.get("color") == "green":
        autonomous = ("BALANCED", "green", "HRV and resting HR are both inside the athlete's established range.")
    else:
        autonomous = ("MIXED", "grey", "Autonomic markers are not aligned strongly enough for a single directional call.")

    sq = metrics.get("sleep_quality")
    subjective_down = (feeling_trend or {}).get("label") == "TRENDING DOWN"
    if sleep.get("color") == "red" and (sq in (3, 4) or subjective_down):
        recovery = ("LOW", "red", "Sleep is well below habitual opportunity and another recovery signal is also negative.")
    elif sleep.get("color") in ("red", "orange") or sq in (3, 4) or subjective_down:
        recovery = ("WATCH", "orange", "At least one sleep/subjective recovery signal is below the athlete's recent norm.")
    else:
        recovery = ("NORMAL", "green", "Sleep opportunity/quality and subjective context do not show a major recovery warning.")

    state = (training_state or {}).get("state")
    atl_ctl = (training_state or {}).get("atl_ctl")
    if state == "HEALTH HOLD":
        load_state = ("HOLD", "red", "Training-load interpretation is subordinated to the active health restriction.")
    elif atl_ctl is not None and atl_ctl >= 1.18:
        load_state = ("LOADED", "orange", f"ATL/CTL is {atl_ctl:.2f}; acute load is elevated relative to chronic load.")
    elif atl_ctl is not None and atl_ctl <= 0.85:
        load_state = ("FRESH", "green", f"ATL/CTL is {atl_ctl:.2f}; acute load is relatively low versus chronic load.")
    else:
        load_state = ("CONTROLLED", "cyan", "Acute and chronic load are in a broadly controlled relationship for this athlete.")

    ae = aerobic_efficiency or {}
    if not ae.get("available"):
        aerobic = ("LEARNING", "grey", "Not enough comparable steady Z2 sessions yet for a reliable longitudinal efficiency call.")
    else:
        aerobic = (ae.get("status", "STABLE"), ae.get("status_class", "cyan"), ae.get("headline", "Aerobic trend available."))

    pressure = str((metabolic_context or {}).get("glycogen_pressure") or "LOW").upper()
    if pressure == "HIGH":
        energy = ("HIGH DEMAND", "orange", "Recent training creates high glycogen/replenishment pressure; this is a fueling context, not a fatigue diagnosis.")
    elif pressure == "MODERATE":
        energy = ("MODERATE", "cyan", "Recent exercise creates meaningful but manageable glycogen/replenishment demand.")
    else:
        energy = ("LOW DEMAND", "green", "Recent exercise-only glycogen pressure is currently low.")

    entries = [
        ("AUTONOMIC", "❤️", autonomous),
        ("RECOVERY", "😴", recovery),
        ("TRAINING LOAD", "⚡", load_state),
        ("AEROBIC", "🫁", aerobic),
        ("ENERGY", "🍚", energy),
    ]
    return {
        "systems": [
            {"label": label, "icon": icon, "status": values[0], "status_class": values[1], "reason": values[2]}
            for label, icon, values in entries
        ],
        "note": "Training/recovery interpretation only · not a medical diagnosis. THE LAB keeps the systems separate instead of hiding them inside one opaque score.",
    }


def training_state_text(state):
    if not state:
        return "TRAINING STATE: unavailable"
    return "\n".join([
        f"TRAINING STATE (deterministic Python): {state.get('state')} | confidence {state.get('confidence')}",
        f"- {state.get('headline')}",
        f"- Why: {state.get('why')}",
        "- Signals: " + (" | ".join(state.get("signals") or []) or "insufficient trend data"),
    ])


def adaptive_sleep_text(adaptive):
    if not adaptive or not adaptive.get("available"):
        return "ADAPTIVE SLEEP BASELINE: insufficient data"
    return (
        "ADAPTIVE SLEEP BASELINE (42-day habitual opportunity; Garmin 7h38 is reference only):\n"
        f"- Current context: {adaptive.get('kind')} | habitual {adaptive.get('habitual_label')} | current delta {adaptive.get('current_delta_min'):+d} min | {adaptive.get('status')}\n"
        f"- Weekday habitual {adaptive.get('weekday_label')} | weekend habitual {adaptive.get('weekend_label')} | 14d trend {adaptive.get('trend_label')}"
    )


def aerobic_efficiency_text(ae):
    if not ae or not ae.get("available"):
        return "AEROBIC EFFICIENCY / DURABILITY: learning; insufficient comparable non-HEAT steady Z2 sessions."
    return (
        f"AEROBIC EFFICIENCY / DURABILITY ({ae.get('cohort_label')}): {ae.get('status')} | confidence {ae.get('confidence')}\n"
        f"- Recent power/HR {ae.get('recent_ratio')} W/bpm vs prior {ae.get('baseline_ratio')} | change {ae.get('trend_pct'):+.1f}%\n"
        f"- Recent decoupling {ae.get('recent_decoupling')}% vs prior {ae.get('baseline_decoupling')}%. HEAT sessions excluded from this baseline."
    )


def power_model_text(model):
    if not model or not model.get("available"):
        return "POWER MODEL: unavailable / insufficient power-curve points."
    r = model.get("recent") or {}
    s = model.get("season") or {}
    lines = [
        "POWER MODEL (two-parameter field estimate; P = CP + W′/t; not a lab CP test):",
        f"- 42d: CP {r.get('cp')} W | W′ {r.get('w_prime_kj')} kJ | fit R² {r.get('r2')} | {r.get('confidence')}",
    ]
    if s.get("available"):
        lines.append(f"- Current season: CP {s.get('cp')} W | W′ {s.get('w_prime_kj')} kJ | fit R² {s.get('r2')}")
        lines.append(f"- 42d vs season CP: {model.get('cp_gap_w'):+d} W | {model.get('status')}")
    if model.get("cp_wkg") is not None:
        lines.append(f"- 42d CP relative to current weight: {model.get('cp_wkg')} W/kg")
    return "\n".join(lines)


def physiological_state_text(state):
    if not state:
        return "PHYSIOLOGICAL STATE: unavailable"
    lines = ["PHYSIOLOGICAL STATE MATRIX (deterministic; not a medical diagnosis):"]
    for item in state.get("systems") or []:
        lines.append(f"- {item.get('label')}: {item.get('status')} — {item.get('reason')}")
    return "\n".join(lines)


def build_week_memory(recent_activities, now=None):
    """Reconstruct the current Monday→now training week directly from Intervals.icu.

    This is fresh on every snapshot, so it survives deploys and does not rely on
    Claude remembering what happened yesterday.
    """
    now = now or get_rome_now()
    today = now.date()
    monday = today - timedelta(days=today.weekday())
    items = []

    for activity in recent_activities:
        raw = activity.get("start_date_local") or ""
        dt = parse_local_activity_datetime(raw)
        if not dt:
            continue
        d = dt.date()
        if d < monday or d > today:
            continue
        # If an activity is timestamped later today than the snapshot, ignore it.
        if d == today and dt.time() > now.replace(tzinfo=None).time():
            continue

        family = classify_training_family(activity)
        duration_sec = activity.get("moving_time") or activity.get("elapsed_time") or 0
        item = {
            "date": d.isoformat(),
            "day": d.strftime("%A"),
            "day_short": d.strftime("%a"),
            "time": dt.strftime("%I:%M %p"),
            "name": activity.get("name") or activity.get("type") or "Activity",
            "family": family,
            "family_short": family.replace("Endurance / ", "").replace(" / Mixed", ""),
            "duration_min": round(duration_sec / 60) if duration_sec else None,
            "load": activity.get("icu_training_load"),
            "hard": is_hard_training_family(family),
        }
        items.append(item)

    items.sort(key=lambda x: (x["date"], x["time"]))
    hard_items = [x for x in items if x["hard"]]
    hard_families = []
    for x in hard_items:
        if x["family"] not in hard_families:
            hard_families.append(x["family"])

    # Days since the most recent hard session is useful spacing information for Claude.
    last_hard = hard_items[-1] if hard_items else None
    days_since_last_hard = None
    if last_hard:
        days_since_last_hard = (today - date.fromisoformat(last_hard["date"])).days

    return {
        "week_start": monday.isoformat(),
        "week_end": today.isoformat(),
        "activities": items,
        "hard_count": len(hard_items),
        "hard_families": hard_families,
        "hard_summary": ", ".join(hard_families),
        "last_hard": last_hard,
        "days_since_last_hard": days_since_last_hard,
    }


def week_memory_text(memory):
    if not memory or not memory.get("activities"):
        return (
            "CURRENT WEEK TRAINING HISTORY (Monday to snapshot time):\n"
            "- No completed activities found yet this week."
        )

    lines = ["CURRENT WEEK TRAINING HISTORY (Monday to snapshot time — authoritative):"]
    for a in memory["activities"]:
        dur = f'{a["duration_min"]} min' if a.get("duration_min") is not None else "duration n/a"
        load = a.get("load") if a.get("load") is not None else "n/a"
        quality = "HARD/QUALITY" if a.get("hard") else "easy/moderate"
        lines.append(
            f'- {a["day"]} {a["date"]} {a["time"]} | {a["family"]} | {quality} | '
            f'{dur} | load {load} | {a["name"]}'
        )
    if memory.get("last_hard"):
        lh = memory["last_hard"]
        lines.append(
            f'- Most recent hard/quality stimulus: {lh["family"]} on {lh["day"]} {lh["date"]} '
            f'({memory.get("days_since_last_hard")} day(s) ago).'
        )
    lines.append(
        "Use this history before prescribing the next sessions. Do not repeat the same hard workout family "
        "simply because it fits the next slot. In particular, avoid another TTE/threshold, VO2max, Over-Under "
        "or sprint/neuromuscular stimulus too close to the same family already completed. Prefer complementary "
        "work and adequate spacing. A repeat is allowed only when there is a clear coaching reason, and that "
        "reason must be stated explicitly in the session rationale."
    )
    return "\n".join(lines)


def _positive_intensity_term(value, patterns):
    """Return True only when a quality term is used as a positive prescription.

    The Coach sometimes writes endurance ceilings such as "no sustained efforts
    above tempo" or "stay below threshold" inside the intensity field. Earlier
    versions treated the mere presence of TEMPO/THRESHOLD/VO2 as proof of a hard
    session, which could incorrectly promote a long Z2 ride to the ~80 g/h hard-
    outdoor fueling baseline. V28 inspects the local language before each quality
    term and ignores negated/ceiling references.
    """
    v = str(value or "").lower().replace("vo₂", "vo2")
    if not v:
        return False
    negative_cues = re.compile(
        r"\b(?:no|not|without|avoid|avoiding|never|resist|resisting|below|under|beneath|"
        r"non|senza|evita|evitare|sotto)\b"
    )
    # Work inside the current clause so a previous "no" does not suppress a real
    # quality prescription later in the sentence.
    clause_break = re.compile(r"[;,.]|\s+[–—]\s+|\n")
    for pattern in patterns:
        for match in re.finditer(pattern, v):
            prefix = v[max(0, match.start() - 72):match.start()]
            clause_prefix = clause_break.split(prefix)[-1]
            if negative_cues.search(clause_prefix):
                continue
            return True
    return False


def intensity_class(value):
    """Classify the prescribed session, not words used to describe its ceiling."""
    v = str(value or "").lower().replace("vo₂", "vo2")

    positive_vo2 = _positive_intensity_term(v, (r"\bvo2(?:max)?\b", r"\banaer(?:obic|obico|obica)?\b"))
    positive_threshold = _positive_intensity_term(v, (r"\bthreshold\b", r"\bsoglia\b"))
    positive_tempo = _positive_intensity_term(v, (r"\btempo\b", r"\bsweet\s*spot\b", r"\bsweetspot\b"))

    if positive_vo2:
        return "vo2"
    if positive_threshold:
        return "threshold"
    if positive_tempo:
        return "tempo"
    if any(k in v for k in ("recover", "recovery", "easy", "facile", "recupero")):
        return "recovery"
    return "endurance"


def normalize_next_sessions(raw_sessions, clock):
    raw_sessions = raw_sessions if isinstance(raw_sessions, list) else []
    normalized = []
    for idx, slot in enumerate(clock.get("next_slots") or []):
        raw = raw_sessions[idx] if idx < len(raw_sessions) and isinstance(raw_sessions[idx], dict) else {}
        planned_env = slot.get("training_environment") if slot.get("is_planned_training") else None
        planned_demand = slot.get("training_demand") if slot.get("is_planned_training") else None

        if slot.get("is_race"):
            normalized.append({
                "slot": slot["label"], "date": slot.get("date"), "period": "RACE",
                "title": slot.get("event_title") or "Race day", "duration": "Priority event",
                "intensity": "Race", "intensity_class": "vo2",
                "main_set": "Race day. No additional training session is prescribed for this slot.",
                "why": "This registered race/event has priority over routine training.",
                "restriction": "RACE", "environment": "OUTDOOR", "planned_demand": "RACE",
                "is_planned_training": False,
            })
            continue

        if slot.get("restriction") == "NO_INTENSITY":
            normalized.append({
                "slot": slot["label"], "date": slot.get("date"), "period": slot.get("period"),
                "title": "Aerobic endurance · restriction active", "duration": str(raw.get("duration") or "Up to 60 min"),
                "intensity": "Z1–Z2 only", "intensity_class": "recovery",
                "main_set": "Easy aerobic riding only. No threshold, VO₂, over-under, sprint or other intentional intensity.",
                "why": f'Python-enforced no-intensity restriction is active through {slot.get("restriction_until") or "the active restriction end date"}; health/availability constraints outrank the AI prescription and any planned-training demand.',
                "restriction": "NO_INTENSITY",
                "environment": planned_env or ATHLETE_FUELING_PROFILE["default_training_environment"],
                "planned_demand": planned_demand,
                "is_planned_training": bool(slot.get("is_planned_training")),
            })
            continue

        intensity = str(raw.get("intensity") or ("Endurance" if slot.get("period") == "AM" else "Training"))
        cls = intensity_class(intensity)
        title = str(raw.get("title") or (slot.get("event_title") if slot.get("is_planned_training") else None) or ("Aerobic endurance" if slot.get("period") == "AM" else "Coach-selected session"))
        main_set = str(raw.get("main_set") or "See coach recommendation.")
        why = str(raw.get("why") or ("Built around the athlete's planned training commitment and current recovery context." if slot.get("is_planned_training") else "Selected from current recovery, load, timing and event context."))

        # EASY is a real ceiling because the athlete explicitly planned an easy
        # outing. HARD remains expected demand rather than a blind override: the
        # coach can still back off for recovery/taper, while fueling sees intent.
        if slot.get("is_planned_training") and planned_demand == "EASY" and cls not in ("recovery", "endurance"):
            intensity = "Easy aerobic / recovery"
            cls = "recovery"
            main_set = "Keep the athlete-planned session easy: Z1–Z2 only, with no intentional threshold, VO₂, over-under or sprint work."
            why = "The Calendar marks this planned training as EASY; Python prevents an accidental hard prescription."

        normalized.append({
            "slot": slot["label"], "date": slot.get("date"), "period": slot.get("period"),
            "title": title, "duration": str(raw.get("duration") or "Up to 60 min"), "intensity": intensity,
            "intensity_class": cls, "main_set": main_set, "why": why,
            "restriction": "NONE",
            "environment": planned_env or ATHLETE_FUELING_PROFILE["default_training_environment"],
            "planned_demand": planned_demand,
            "is_planned_training": bool(slot.get("is_planned_training")),
        })
    return normalized




def _nutrition_number(value):
    try:
        value = float(value)
    except (TypeError, ValueError):
        return None
    return value if math.isfinite(value) else None


def _activity_local_dt(activity):
    raw = str(activity.get("start_date_local") or "")
    if not raw:
        return None
    try:
        return datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError:
        try:
            return datetime.strptime(raw[:16], "%Y-%m-%dT%H:%M")
        except ValueError:
            return None


def build_weight_context(season_wellness, now=None):
    """Return a dated weight value and an explicit confidence state.

    Precise carb-loading totals in grams are never calculated from a stale or
    missing weight. The g/kg reference can still be shown, but THE LAB asks for
    a fresh body weight before turning it into an apparently precise daily total.
    """
    now = now or get_rome_now()
    entries = []
    for w in season_wellness or []:
        kg = _nutrition_number(w.get("weight"))
        ds = str(w.get("id") or "")[:10]
        if kg is None or kg <= 0:
            continue
        try:
            d = date.fromisoformat(ds)
        except ValueError:
            continue
        entries.append((d, kg))
    if not entries:
        return {
            "kg": None, "date": None, "age_days": None, "status": "MISSING",
            "needs_update": True, "label": "No weight in the current data window",
            "detail": "Update body weight before calculating a precise carb-loading total.",
        }
    d, kg = max(entries, key=lambda x: x[0])
    age = max(0, (now.date() - d).days)
    current_days = ATHLETE_FUELING_PROFILE["weight_current_days"]
    aging_days = ATHLETE_FUELING_PROFILE["weight_aging_days"]
    if age <= current_days:
        status, needs_update = "CURRENT", False
        detail = f"{kg:.1f} kg · measured {age} day(s) ago."
    elif age <= aging_days:
        status, needs_update = "AGING", False
        detail = f"{kg:.1f} kg · {age} days old. Usable for context, but refresh it before race week if practical."
    else:
        status, needs_update = "STALE", True
        detail = f"{kg:.1f} kg · {age} days old. Update weight before a precise carb-loading total is calculated."
    return {
        "kg": round(kg, 1), "date": d.isoformat(), "age_days": age,
        "status": status, "needs_update": needs_update,
        "label": f"{kg:.1f} kg · {status}", "detail": detail,
    }


def assess_intervals_cho(activity):
    """Sanity-check Intervals.icu's estimated carbohydrate utilisation.

    Intervals exposes carbs_used and carbs_ingested. carbs_used is modelled, not
    directly measured. Known model limitations make very short/long sessions and
    impossible energy relationships unsuitable for quantitative glycogen context.
    """
    used = _nutrition_number(activity.get("carbs_used"))
    ingested = _nutrition_number(activity.get("carbs_ingested")) or 0.0
    kcal = _nutrition_number(activity.get("calories"))
    secs = _nutrition_number(activity.get("moving_time") or activity.get("elapsed_time")) or 0.0
    mins = secs / 60.0
    result = {
        "used_g": round(used, 1) if used is not None else None,
        "ingested_g": round(max(0.0, ingested), 1),
        "valid": False, "reason": "No Intervals CHO-use estimate", "duration_min": round(mins, 1),
    }
    if used is None or used < 0:
        return result
    if mins < 30 or mins > 90:
        result["reason"] = "Low confidence: Intervals CHO model is least reliable outside roughly 30–90 min"
        return result
    if kcal is not None and kcal > 0 and used * 4.0 > kcal * 1.10:
        result["reason"] = "Low confidence: estimated CHO energy exceeds total session calories"
        return result
    result["valid"] = True
    result["reason"] = "Accepted as a model estimate after duration/energy sanity checks"
    return result


def build_metabolic_context(recent_activities, season_wellness, planning_context, now=None):
    """Build deterministic energy/glycogen/race context before the AI is called."""
    now = now or get_rome_now()
    planning_context = planning_context or {}
    local_now = now.replace(tzinfo=None) if now.tzinfo else now
    since36 = local_now - timedelta(hours=36)
    since48 = local_now - timedelta(hours=48)
    acts36, acts48 = [], []
    for a in recent_activities or []:
        dt = _activity_local_dt(a)
        if not dt:
            continue
        if dt.tzinfo:
            dt = dt.astimezone(ROME_TZ).replace(tzinfo=None)
        if dt >= since48:
            acts48.append(a)
        if dt >= since36:
            acts36.append(a)

    kcal36 = round(sum(_nutrition_number(a.get("calories")) or 0 for a in acts36))
    kcal48 = round(sum(_nutrition_number(a.get("calories")) or 0 for a in acts48))
    load48 = round(sum(_nutrition_number(a.get("icu_training_load")) or 0 for a in acts48), 1)
    hard48 = sum(1 for a in acts48 if is_hard_training_family(classify_training_family(a)))

    cho_checks = [assess_intervals_cho(a) for a in acts48]
    valid_cho = [c for c in cho_checks if c["valid"]]
    invalid_cho = [c for c in cho_checks if c.get("used_g") is not None and not c["valid"]]
    used48 = round(sum(c["used_g"] or 0 for c in valid_cho), 1) if valid_cho else None
    ingested48 = round(sum(c["ingested_g"] or 0 for c in valid_cho), 1) if valid_cho else None
    exercise_gap = round(max(0.0, (used48 or 0) - (ingested48 or 0)), 1) if valid_cho else None

    score = 0
    if kcal48 >= 1400: score += 2
    elif kcal48 >= 700: score += 1
    if load48 >= 140: score += 2
    elif load48 >= 70: score += 1
    if hard48 >= 2: score += 2
    elif hard48 == 1: score += 1
    if exercise_gap is not None:
        if exercise_gap >= 160: score += 2
        elif exercise_gap >= 80: score += 1
    glycogen_pressure = "HIGH" if score >= 5 else ("MODERATE" if score >= 2 else "LOW")

    weight = build_weight_context(season_wellness, now)
    race = planning_context.get("next_race") or None
    health = planning_context.get("health_override")
    if not race:
        race_state = "OFF"
        race_detail = "No upcoming race is registered in the active planning horizon."
    elif health or race.get("conflict"):
        race_state = "PAUSED"
        race_detail = "Health/restriction context outranks race-prep nutrition until the conflict is resolved."
    else:
        days = int(race.get("days_away") or 0)
        if days <= 0:
            race_state = "RACE DAY"
            race_detail = "Race day: prioritize pre-race availability and the athlete's practised ~100 g CHO/h race fueling strategy."
        elif days <= ATHLETE_FUELING_PROFILE["carb_loading_active_days"]:
            race_state = "ACTIVE"
            race_detail = "Carbohydrate-loading relevance is high: raise daily carbohydrate availability rather than judging recovery meal-by-meal."
        elif days <= ATHLETE_FUELING_PROFILE["carb_loading_approaching_days"]:
            race_state = "APPROACHING"
            race_detail = "Race carbohydrate-loading window is approaching; begin protecting glycogen availability while taper volume falls."
        else:
            race_state = "NOT YET"
            race_detail = f"Race is {days} days away; deliberate carbohydrate loading is not active yet."

    gkg_low = ATHLETE_FUELING_PROFILE["carb_loading_gkg_low"]
    gkg_high = ATHLETE_FUELING_PROFILE["carb_loading_gkg_high"]
    total_range = None
    if race_state == "ACTIVE" and weight.get("kg") and not weight.get("needs_update"):
        lo = int(round(weight["kg"] * gkg_low / 10.0) * 10)
        hi = int(round(weight["kg"] * gkg_high / 10.0) * 10)
        total_range = f"~{lo}–{hi} g CHO/day"

    return {
        "kcal_36h": kcal36, "kcal_48h": kcal48, "load_48h": load48,
        "hard_sessions_48h": hard48, "glycogen_pressure": glycogen_pressure,
        "cho_used_48h": used48, "cho_ingested_48h": ingested48,
        "exercise_cho_gap_48h": exercise_gap, "cho_valid_count": len(valid_cho),
        "cho_low_confidence_count": len(invalid_cho), "weight": weight,
        "race_strategy": {
            "state": race_state, "detail": race_detail,
            "title": race.get("title") if race else None,
            "date": race.get("start_date") if race else None,
            "days_away": race.get("days_away") if race else None,
            "race_fueling": f'~{ATHLETE_FUELING_PROFILE["race_g_per_hour"]} g CHO/h',
            "loading_gkg": f"{gkg_low:.0f}–{gkg_high:.0f} g/kg/day reference" if race_state in ("ACTIVE", "APPROACHING") else None,
            "loading_total": total_range,
            "weight_update_required": bool(race_state == "ACTIVE" and weight.get("needs_update")),
        },
    }


def metabolic_context_text(context):
    c = context or {}
    r = c.get("race_strategy") or {}
    w = c.get("weight") or {}
    used = c.get("cho_used_48h")
    ing = c.get("cho_ingested_48h")
    gap = c.get("exercise_cho_gap_48h")
    cho_line = "No reliable Intervals CHO-use estimate in the last 48h."
    if used is not None:
        cho_line = f"Accepted Intervals estimate: {used} g CHO used; {ing or 0} g recorded ingested; exercise-only gap {gap} g."
    return (
        "NUTRITION / GLYCOGEN CONTEXT (Python-derived; use for reasoning, do not invent glycogen stores):\n"
        f'- Athlete fueling baseline: race ~{ATHLETE_FUELING_PROFILE["race_g_per_hour"]} g CHO/h; hard outdoor training ~{ATHLETE_FUELING_PROFILE["hard_outdoor_g_per_hour"]} g/h; indoor training usually 0 g/h during the session, with carbohydrate handled in recovery.\n'
        f'- Duration-aware outdoor baseline: 90–150 min endurance ~{ATHLETE_FUELING_PROFILE["medium_outdoor_gph_low"]}–{ATHLETE_FUELING_PROFILE["medium_outdoor_gph_high"]} g/h; >150 min endurance ~{ATHLETE_FUELING_PROFILE["long_outdoor_gph_low"]}–{ATHLETE_FUELING_PROFILE["long_outdoor_gph_high"]} g/h even when intensity is Z2/easy, because duration itself increases carbohydrate demand.\n'
        f'- Completed training last 36h: {c.get("kcal_36h", 0)} kcal. Last 48h: {c.get("kcal_48h", 0)} kcal, load {c.get("load_48h", 0)}, hard/quality sessions {c.get("hard_sessions_48h", 0)}.\n'
        f'- Glycogen replenishment pressure: {c.get("glycogen_pressure", "LOW")}. {cho_line} Low-confidence CHO estimates ignored: {c.get("cho_low_confidence_count", 0)}.\n'
        f'- Weight confidence: {w.get("status", "MISSING")} | {w.get("detail", "No weight available")}.\n'
        f'- Race carb strategy: {r.get("state", "OFF")} | {r.get("detail", "")}' + (f' | {r.get("loading_gkg")}' if r.get("loading_gkg") else '') + (f' | {r.get("loading_total")}' if r.get("loading_total") else '') + "\n"
        "- CRITICAL INTERPRETATION RULE: keep SESSION DEMAND, DURATION DEMAND and RECOVERY NEED separate. A long easy/Z2 ride can remain LOW or LOW–MODERATE intensity demand while still requiring substantial intra-ride carbohydrate and HIGH daily replenishment priority.\n"
        "- POST-RIDE RULE: an initial recovery target is the first feeding, not an instruction to replace all ride calories immediately. For long rides, reason across the following meals and the whole-day carbohydrate/energy context. If recovery time is <4 h, rapid glycogen restoration can justify ~1.0–1.2 g/kg/h.\n"
        "- If carb loading is ACTIVE and weight is stale/missing, explicitly ask the athlete to update weight before giving a precise total grams/day target."
    )


def classify_upcoming_session_demand(session_item):
    """Classify prescribed demand from structured fields, never main-set prose."""
    restriction = str(session_item.get("restriction") or "").upper()
    intensity_cls = str(session_item.get("intensity_class") or "endurance").lower()
    title = str(session_item.get("title") or "").lower()
    intensity = str(session_item.get("intensity") or "").lower()
    short_text = f"{title} {intensity}"
    planned_demand = str(session_item.get("planned_demand") or "").upper() or None

    if restriction == "RACE" or str(session_item.get("period") or "").upper() == "RACE":
        kind = "RACE"
    elif restriction == "NO_INTENSITY" or intensity_cls == "recovery" or planned_demand == "EASY":
        kind = "RECOVERY"
    elif intensity_cls == "endurance":
        kind = "HEAT" if any(k in short_text for k in ("heat", "thermal", "hot room", "caldo")) else "ENDURANCE"
    elif intensity_cls == "tempo":
        kind = "TEMPO"
    elif intensity_cls == "threshold":
        kind = "THRESHOLD"
    elif intensity_cls == "vo2":
        kind = "VO2"
    else:
        kind = "ENDURANCE"

    demand = {
        "RECOVERY": "LOW", "ENDURANCE": "LOW–MODERATE", "HEAT": "MODERATE",
        "TEMPO": "MODERATE–HIGH", "THRESHOLD": "HIGH", "VO2": "HIGH", "RACE": "VERY HIGH",
    }[kind]
    if planned_demand == "HARD" and kind != "RECOVERY" and restriction not in ("NO_INTENSITY", "RACE"):
        demand = "HIGH"
    elif planned_demand == "NORMAL" and kind in ("RECOVERY", "ENDURANCE") and restriction != "NO_INTENSITY":
        demand = "MODERATE"

    structured_env = str(session_item.get("environment") or "").upper()
    if structured_env in ("INDOOR", "OUTDOOR"):
        environment = structured_env
    else:
        explicit_outdoor = any(k in short_text for k in ("outdoor", "road", "outside", "granfondo", "gran fondo", "race"))
        explicit_indoor = any(k in short_text for k in ("indoor", "zwift", "trainer"))
        environment = "OUTDOOR" if (kind == "RACE" or explicit_outdoor) else ("INDOOR" if explicit_indoor else ATHLETE_FUELING_PROFILE["default_training_environment"])
    return {"kind": kind, "demand": demand, "environment": environment, "planned_demand": planned_demand}



def _parse_duration_minutes(value):
    """Best-effort parser for Coach duration strings such as 4 h, 3h30, 90 min or 1:45.

    For a displayed range (e.g. 3–4 h or 90–120 min), use the upper bound for
    fueling so THE LAB does not under-fuel the planned session merely because the
    exact finish time is flexible.
    """
    if isinstance(value, (int, float)):
        v = _nutrition_number(value)
        return round(v, 1) if v and v > 0 else None
    text = str(value or "").strip().lower().replace(",", ".")
    if not text:
        return None

    hr_range = re.search(r"(\d+(?:\.\d+)?)\s*[–—-]\s*(\d+(?:\.\d+)?)\s*(?:hours?|hrs?|h|ore|ora)\b", text)
    if hr_range:
        return round(float(hr_range.group(2)) * 60.0, 1)
    min_range = re.search(r"(\d+(?:\.\d+)?)\s*[–—-]\s*(\d+(?:\.\d+)?)\s*(?:minutes?|mins?|min|m)\b", text)
    if min_range:
        return round(float(min_range.group(2)), 1)

    clock = re.search(r"(?<!\d)(\d{1,2}):(\d{2})(?!\d)", text)
    if clock:
        hours, minutes = int(clock.group(1)), int(clock.group(2))
        if minutes < 60:
            return round(hours * 60.0 + minutes, 1)

    hour = re.search(r"(\d+(?:\.\d+)?)\s*(?:hours?|hrs?|h|ore|ora)", text)
    minute = re.search(r"(\d+(?:\.\d+)?)\s*(?:minutes?|mins?|min|m)\b", text)
    if hour:
        total = float(hour.group(1)) * 60.0
        # Handles compact forms such as 3h30 or 3h30m.
        tail = text[hour.end():]
        compact_min = re.match(r"\s*(\d{1,2})(?:\s*(?:minutes?|mins?|min|m))?\b", tail)
        if compact_min:
            total += float(compact_min.group(1))
        elif minute and minute.start() >= hour.end():
            total += float(minute.group(1))
        return round(total, 1) if total > 0 else None
    if minute:
        return round(float(minute.group(1)), 1)
    return None


def _session_duration_minutes(session_item):
    for key in ("duration_minutes", "duration_min"):
        value = _nutrition_number((session_item or {}).get(key))
        if value and value > 0:
            return round(value, 1)
    return _parse_duration_minutes((session_item or {}).get("duration"))


def _format_duration_hours(duration_min):
    if not duration_min:
        return None
    hours = duration_min / 60.0
    if abs(hours - round(hours)) < 0.05:
        return f"{int(round(hours))} h"
    return f"{hours:.1f} h"


def _fuel_total_display(low_gph, high_gph, duration_min):
    if duration_min is None or low_gph is None or high_gph is None or high_gph <= 0:
        return None
    hours = duration_min / 60.0
    low_total = int(round((low_gph * hours) / 10.0) * 10)
    high_total = int(round((high_gph * hours) / 10.0) * 10)
    dur = _format_duration_hours(duration_min)
    if low_gph == high_gph:
        return f"~{high_total} g CHO across {dur}"
    return f"~{low_total}–{high_total} g CHO across {dur}"


# V28 guardrail: intra-session fueling must follow the normalized physiological
# prescription. Negative mentions such as "no tempo" or "below threshold" are
# not allowed to turn an ENDURANCE/Z2 session into HARD OUTDOOR.
def _intra_fueling_strategy(kind, environment, planned_demand, duration_min):
    """Return athlete-specific intra-session CHO, with duration as its own axis."""
    if kind == "RACE":
        g = ATHLETE_FUELING_PROFILE["race_g_per_hour"]
        return {
            "display": f"~{g} g CHO/h", "label": "PRACTISED RACE TARGET",
            "low_gph": g, "high_gph": g,
            "total": _fuel_total_display(g, g, duration_min),
            "duration_driver": "RACE",
        }

    if environment == "INDOOR":
        g = ATHLETE_FUELING_PROFILE["indoor_default_g_per_hour"]
        return {
            "display": f"{g} g/h usual", "label": "INDOOR BASELINE",
            "low_gph": g, "high_gph": g, "total": None,
            "duration_driver": "ATHLETE BASELINE",
        }

    if environment != "OUTDOOR":
        return {
            "display": "No fixed target", "label": "MATCH DURATION / DEMAND",
            "low_gph": None, "high_gph": None, "total": None,
            "duration_driver": "UNKNOWN DURATION/ENVIRONMENT",
        }

    hard_quality = (
        (planned_demand == "HARD" and kind != "RECOVERY")
        or kind in ("TEMPO", "THRESHOLD", "VO2")
    )
    if hard_quality:
        g = ATHLETE_FUELING_PROFILE["hard_outdoor_g_per_hour"]
        return {
            "display": f"~{g} g CHO/h", "label": "HARD OUTDOOR BASELINE",
            "low_gph": g, "high_gph": g,
            "total": _fuel_total_display(g, g, duration_min),
            "duration_driver": "INTENSITY + DURATION" if duration_min else "INTENSITY",
        }

    medium_min = ATHLETE_FUELING_PROFILE["medium_outdoor_min"]
    long_min = ATHLETE_FUELING_PROFILE["long_outdoor_min"]
    if duration_min is not None and duration_min > long_min:
        lo = ATHLETE_FUELING_PROFILE["long_outdoor_gph_low"]
        hi = ATHLETE_FUELING_PROFILE["long_outdoor_gph_high"]
        return {
            "display": f"{lo}–{hi} g CHO/h", "label": "LONG ENDURANCE · DURATION-DRIVEN",
            "low_gph": lo, "high_gph": hi,
            "total": _fuel_total_display(lo, hi, duration_min),
            "duration_driver": "HIGH",
        }
    if duration_min is not None and duration_min >= medium_min:
        lo = ATHLETE_FUELING_PROFILE["medium_outdoor_gph_low"]
        hi = ATHLETE_FUELING_PROFILE["medium_outdoor_gph_high"]
        return {
            "display": f"{lo}–{hi} g CHO/h", "label": "ENDURANCE · DURATION-AWARE",
            "low_gph": lo, "high_gph": hi,
            "total": _fuel_total_display(lo, hi, duration_min),
            "duration_driver": "MODERATE",
        }
    if duration_min is not None:
        return {
            "display": "0–30 g CHO/h", "label": "SHORT OUTDOOR · OPTIONAL / CONTEXTUAL",
            "low_gph": 0, "high_gph": 30,
            "total": _fuel_total_display(0, 30, duration_min),
            "duration_driver": "LOW",
        }
    return {
        "display": "No fixed target", "label": "MATCH DURATION / DEMAND",
        "low_gph": None, "high_gph": None, "total": None,
        "duration_driver": "UNKNOWN",
    }


def _session_clock(session_item):
    ds = str(session_item.get("date") or "")[:10]
    try:
        d = date.fromisoformat(ds)
    except ValueError:
        return None
    period = str(session_item.get("period") or "").upper()
    hour = 9 if period == "RACE" else (8 if period == "AM" else 18)
    return datetime.combine(d, datetime.min.time()).replace(hour=hour)


def _base_post_workout_range(kind, metabolic_context, next_gap_hours=None):
    """Legacy session-scaled first-feeding target for non-long sessions."""
    base = {
        "RECOVERY": (0, 20), "ENDURANCE": (0, 30), "HEAT": (30, 40),
        "TEMPO": (40, 50), "THRESHOLD": (50, 60), "VO2": (50, 60), "RACE": (60, 90),
    }[kind]
    boost = 0
    pressure = str((metabolic_context or {}).get("glycogen_pressure") or "LOW")
    if pressure == "HIGH": boost += 15
    elif pressure == "MODERATE": boost += 5
    if next_gap_hours is not None:
        if next_gap_hours <= 10: boost += 10
        elif next_gap_hours <= 20: boost += 5
    race_state = str(((metabolic_context or {}).get("race_strategy") or {}).get("state") or "OFF")
    if race_state == "ACTIVE": boost += 20
    elif race_state == "APPROACHING": boost += 10
    caps = {"RECOVERY": 60, "ENDURANCE": 60, "HEAT": 70, "TEMPO": 80, "THRESHOLD": 90, "VO2": 90, "RACE": 100}
    lo = min(caps[kind], base[0] + boost)
    hi = min(caps[kind], base[1] + boost)
    lo = int(round(lo / 10.0) * 10)
    hi = int(round(hi / 10.0) * 10)
    if hi <= 20:
        return "0–20 g CHO", "LIGHT"
    if lo == hi:
        return f"~{hi} g CHO", "MODERATE" if hi < 60 else "HIGH"
    return f"{lo}–{hi} g CHO", "MODERATE" if hi < 60 else "HIGH"


def _weight_scaled_target(weight_context, low_gkg, high_gkg=None, per_hour=False, suffix=""):
    high_gkg = low_gkg if high_gkg is None else high_gkg
    weight_context = weight_context or {}
    kg = _nutrition_number(weight_context.get("kg"))
    usable = bool(kg and kg > 0 and not weight_context.get("needs_update"))
    unit = "g CHO/h" if per_hour else "g CHO"
    if usable:
        lo = int(round((kg * low_gkg) / 5.0) * 5)
        hi = int(round((kg * high_gkg) / 5.0) * 5)
        amount = f"~{lo} {unit}" if lo == hi else f"~{lo}–{hi} {unit}"
        return f"{amount}{suffix}"
    amount = f"~{low_gkg:.1f} g/kg" if abs(low_gkg - high_gkg) < 0.01 else f"~{low_gkg:.1f}–{high_gkg:.1f} g/kg"
    if per_hour:
        amount += "/h"
    return f"{amount} CHO{suffix}"


def _post_workout_strategy(kind, metabolic_context, next_gap_hours=None, duration_min=None):
    """Separate the first recovery feeding from whole-day replenishment priority."""
    metabolic_context = metabolic_context or {}
    pressure = str(metabolic_context.get("glycogen_pressure") or "LOW")
    race_state = str((metabolic_context.get("race_strategy") or {}).get("state") or "OFF")
    weight = metabolic_context.get("weight") or {}
    long_ride = bool(duration_min is not None and duration_min > ATHLETE_FUELING_PROFILE["long_outdoor_min"])
    medium_ride = bool(duration_min is not None and duration_min >= ATHLETE_FUELING_PROFILE["medium_outdoor_min"])
    rapid_recovery = bool(next_gap_hours is not None and next_gap_hours < 4)

    if rapid_recovery:
        post_cho = _weight_scaled_target(
            weight,
            ATHLETE_FUELING_PROFILE["rapid_recovery_gkg_low"],
            ATHLETE_FUELING_PROFILE["rapid_recovery_gkg_high"],
            per_hour=True,
            suffix=" · first 3–4 h",
        )
        recovery_need = "VERY HIGH"
        post_label = "RAPID GLYCOGEN RESTORATION"
    elif long_ride or kind == "RACE":
        gkg = ATHLETE_FUELING_PROFILE["long_ride_initial_gkg"]
        post_cho = _weight_scaled_target(weight, gkg, suffix=" initial")
        recovery_need = "HIGH"
        post_label = "LONG-RIDE INITIAL RECOVERY" if kind != "RACE" else "POST-RACE INITIAL RECOVERY"
    else:
        post_cho, recovery_need = _base_post_workout_range(kind, metabolic_context, next_gap_hours)
        post_label = None

    priority_score = 0
    if long_ride or kind == "RACE": priority_score += 3
    elif medium_ride: priority_score += 1
    if kind in ("TEMPO", "THRESHOLD", "VO2"): priority_score += 2
    elif kind == "HEAT": priority_score += 1
    if pressure == "HIGH": priority_score += 2
    elif pressure == "MODERATE": priority_score += 1
    if rapid_recovery: priority_score += 3
    elif next_gap_hours is not None and next_gap_hours <= 10: priority_score += 2
    elif next_gap_hours is not None and next_gap_hours <= 20: priority_score += 1
    if race_state == "ACTIVE": priority_score += 2
    elif race_state == "APPROACHING": priority_score += 1

    if long_ride or kind == "RACE" or rapid_recovery:
        daily_priority = "HIGH"
    elif priority_score >= 4:
        daily_priority = "HIGH"
    elif priority_score >= 2:
        daily_priority = "MODERATE"
    else:
        daily_priority = "LOW"

    if rapid_recovery:
        replenishment_guidance = "Short turnaround: distribute carbohydrate repeatedly during the first 3–4 hours. The hourly target is for rapid glycogen restoration, not a one-off meal."
    elif long_ride:
        replenishment_guidance = "The initial target is only the first recovery feeding. A long ride creates substantial cumulative energy and glycogen demand: continue carbohydrate-rich meals/snacks over the next 4–6 hours and across the day rather than trying to replace all ride calories immediately."
    elif kind == "RACE":
        replenishment_guidance = "Treat the first feeding as the start of recovery, then continue carbohydrate and total energy replacement across subsequent meals according to appetite, GI tolerance and the next training demand."
    elif daily_priority == "HIGH":
        replenishment_guidance = "Recent load, race context and/or short turnaround make whole-day carbohydrate availability a priority; do not judge recovery from the first snack alone."
    elif daily_priority == "MODERATE":
        replenishment_guidance = "Use the first recovery feeding as part of the next normal meals; total carbohydrate availability across the day matters more than perfectly matching exercise calories."
    else:
        replenishment_guidance = "Normal meals can cover most recovery needs. The first post-ride target is contextual, not a requirement to replace every exercise calorie immediately."

    return {
        "post_cho": post_cho,
        "recovery_need": recovery_need,
        "post_label_override": post_label,
        "daily_replenishment_priority": daily_priority,
        "replenishment_guidance": replenishment_guidance,
        "rapid_recovery": rapid_recovery,
        "long_ride": long_ride,
        "medium_ride": medium_ride,
    }


def build_nutrition_plan(next_sessions, metabolic_context, now=None):
    """Structured Nutrition Engine: intensity demand != duration demand != recovery need.

    No keyword scan of main_set is allowed here. Session demand comes from the
    normalized intensity class/restriction. Duration independently drives outdoor
    fueling, while recent calories, accepted Intervals CHO estimates, race proximity,
    weight freshness and next-session spacing alter recovery need without changing
    what the workout actually is.
    """
    now = now or get_rome_now()
    metabolic_context = metabolic_context or {}
    sessions = list(next_sessions or [])
    plans = []
    for idx, session_item in enumerate(sessions):
        cls = classify_upcoming_session_demand(session_item)
        kind, demand, environment = cls["kind"], cls["demand"], cls["environment"]
        planned_demand = cls.get("planned_demand")
        duration_min = _session_duration_minutes(session_item)
        current_dt = _session_clock(session_item)
        next_dt = _session_clock(sessions[idx + 1]) if idx + 1 < len(sessions) else None
        gap_hours = None
        if current_dt and next_dt and next_dt > current_dt:
            gap_hours = round((next_dt - current_dt).total_seconds() / 3600.0, 1)

        intra_strategy = _intra_fueling_strategy(kind, environment, planned_demand, duration_min)
        recovery = _post_workout_strategy(kind, metabolic_context, gap_hours, duration_min)
        post_cho = recovery["post_cho"]
        recovery_need = recovery["recovery_need"]
        race_state = str((metabolic_context.get("race_strategy") or {}).get("state") or "OFF")
        pressure = str(metabolic_context.get("glycogen_pressure") or "LOW")

        if recovery.get("post_label_override"):
            post_label = recovery["post_label_override"]
            guidance = recovery["replenishment_guidance"]
        elif kind == "RECOVERY" and (race_state == "ACTIVE" or pressure == "HIGH"):
            post_label = "RACE-PREP / GLYCOGEN TOP-UP" if race_state == "ACTIVE" else "GLYCOGEN TOP-UP"
            guidance = "The ride itself is low demand. The higher recovery target, if shown, comes from recent carbohydrate pressure and/or race preparation — not because this recovery ride is being classified as hard."
        elif kind == "RECOVERY":
            post_label = "LIGHT RECOVERY"
            guidance = "Low-demand ride: a normal carbohydrate-containing meal is usually enough unless duration, recent training or the next session raises replenishment priority."
        elif kind == "HEAT":
            post_label = "HEAT RECOVERY"
            guidance = "Moderate carbohydrate replacement plus fluid/electrolyte replacement; heat stress raises recovery priority without automatically making the workout a hard glycogen session."
        elif kind in ("TEMPO", "THRESHOLD", "VO2"):
            post_label = "GLYCOGEN REPLENISHMENT"
            guidance = "Quality work has meaningful carbohydrate demand. Recovery is scaled further by duration, recent workload, time to the next session and race proximity."
        elif kind == "RACE":
            post_label = "POST-RACE REPLENISHMENT"
            guidance = "Race-day recovery is high priority, but immediate intake should still fit the athlete's overall post-race meal and gastrointestinal tolerance."
        else:
            post_label = "LIGHT–MODERATE REPLENISHMENT"
            guidance = "Aerobic intensity is lower than quality training, but long duration can still create substantial carbohydrate and energy demand. Recovery is scaled by duration, recent load, turnaround and race preparation."

        if recovery.get("rapid_recovery"):
            timing = f"Very high urgency · next session ~{gap_hours:g} h later · begin promptly and repeat feeding across the first 3–4 h"
        elif gap_hours is not None and gap_hours <= 10:
            timing = f"High urgency · next session ~{gap_hours:g} h later · start within ~30–60 min and continue through subsequent meals"
        elif gap_hours is not None and gap_hours <= 20:
            timing = f"Moderate urgency · next session ~{gap_hours:g} h later · first feeding within ~60 min is practical"
        elif recovery.get("long_ride"):
            timing = "High daily priority · start with the next practical feeding, then continue replenishment across the next 4–6 h and the rest of the day"
        else:
            timing = "Normal urgency · integrate with the next normal meal within ~60–90 min"

        plans.append({
            "slot": session_item.get("slot", "Upcoming session"), "title": session_item.get("title") or "Upcoming session",
            "kind": kind, "session_demand": demand, "environment": environment, "planned_demand": planned_demand,
            "duration_min": duration_min, "duration_display": _format_duration_hours(duration_min),
            "duration_driver": intra_strategy.get("duration_driver"),
            "intra_cho": intra_strategy["display"], "intra_label": intra_strategy["label"],
            "intra_total": intra_strategy.get("total"),
            "post_cho": post_cho, "post_label": post_label, "recovery_need": recovery_need,
            "daily_replenishment_priority": recovery["daily_replenishment_priority"],
            "replenishment_guidance": recovery["replenishment_guidance"],
            "guidance": guidance, "timing": timing, "next_gap_hours": gap_hours,
        })
    return plans


# Backward-compatible name retained for any old preview/session object paths.
def build_post_workout_nutrition(next_sessions, metabolic_context=None):
    return build_nutrition_plan(next_sessions, metabolic_context or {
        "glycogen_pressure": "LOW", "race_strategy": {"state": "OFF"}
    })


def personal_baseline_text(metrics):
    pb = metrics.get("personal_baselines") or {}
    adaptive = metrics.get("adaptive_sleep") or pb.get("adaptive_sleep") or {}
    def line(label, key):
        item = pb.get(key) or {}
        return f"- {label}: Garmin {item.get('garmin', 'n/a')} | recent {RECENT_BASELINE_DAYS}d {item.get('recent', 'n/a')} | status {item.get('status', 'n/a')}"
    sleep_line = (
        f"- Sleep duration: habitual {adaptive.get('kind', 'n/a')} {adaptive.get('habitual_label', 'n/a')} "
        f"({SLEEP_BASELINE_DAYS}d adaptive; weekday {adaptive.get('weekday_label', 'n/a')} / weekend {adaptive.get('weekend_label', 'n/a')}) "
        f"| current delta {adaptive.get('current_delta_min', 'n/a')} min | Garmin 7h38m retained as reference, not daily penalty target"
    )
    return "\n".join([
        f"PERSONAL BASELINES ({BASELINE_SOURCE}; sleep opportunity is adaptive):",
        line("HRV", "hrv"),
        line("Resting HR", "rhr"),
        sleep_line,
        line("Sleep Score", "sleep_score"),
        line("SpO2", "spo2"),
        line("Sleeping HR", "sleeping_hr"),
        f"- Sleeping respiration: Garmin {pb.get('sleeping_respiration', {}).get('garmin', '11 brpm')} | live value not currently imported",
        f"- Awake respiration: Garmin {pb.get('awake_respiration', {}).get('garmin', '13–14 brpm')} | live value not currently imported",
    ])

def extract_snapshot_daily_question(logs=None, now=None):
    """Return the most recent explicit question in today's Daily Log, if any.

    Saving a Daily Log remains a zero-AI action. When the athlete subsequently
    generates a Snapshot (which already performs the normal AI Coach call), an
    explicit question written in today's note should be answered inside that same
    Snapshot rather than requiring a second /coach-chat call.
    """
    logs = logs if logs is not None else load_daily_logs(80)
    today_iso = (now or get_rome_now()).date().isoformat()
    today_logs = [
        log for log in (logs or [])
        if str(log.get("local_date") or "") == today_iso
    ]
    if not today_logs:
        return None
    # logged_at_utc is an ISO timestamp and is the safest ordering key.  Only
    # the latest Daily Note is authoritative: an older question should not be
    # resurrected after the athlete has logged a newer note without it.
    today_logs.sort(key=lambda log: str(log.get("logged_at_utc") or ""), reverse=True)
    note = str(today_logs[0].get("note") or "").strip()
    if not note or "?" not in note:
        return None
    return note[:1200]


def ask_claude(data_text, metrics, coach_clock, week_memory, planning_context=None, feeling_trend=None, metabolic_context=None, snapshot_question=None):
    planning_context = planning_context or build_planning_context()
    feeling_trend = feeling_trend or compute_feeling_trend()
    metabolic_context = metabolic_context or {}
    slot_lines = "\n".join(
        f'{i+1}. {slot["label"]} | date {slot["date"]} | restriction {slot.get("restriction", "NONE")}'
        + (f' | planned environment {slot.get("training_environment")} | expected demand {slot.get("training_demand") or "COACH"} | athlete note {slot.get("event_note") or "none"}' if slot.get("is_planned_training") else '')
        for i, slot in enumerate(coach_clock.get("next_slots") or [])
    )
    prompt = (
        "You are an expert cycling coach inside THE LAB. The athlete may train twice per day, but V12 structured health, availability, restriction and event data outranks the theoretical schedule. "
        "The COACH CLOCK and HEALTH / AVAILABILITY / EVENT CONTEXT below are authoritative. Activities already logged are completed. Slots removed by Python do not exist for you. "
        "A NO_INTENSITY slot permits only easy aerobic/recovery work. A RACE slot is the event itself and must not receive an extra workout. A PLANNED slot is an athlete-created commitment: its INDOOR/OUTDOOR environment is authoritative. EASY is an intensity ceiling; HARD is expected demand unless health/restrictions or race-proximity safety justify backing off; COACH means choose from context.\n\n"
        "{planning_context}\n\n"
        "{clock_context}\n\n"
        "{week_context}\n\n"
        "{subjective_context}\n\n"
        "{baseline_context}\n\n"
        "{metabolic_context}\n\n"
        "ATHLETE CONTEXT:\n{athlete_context}\n\n"
        "Current metrics: Fitness (CTL) {ctl} [{fitness_zone}], Fatigue (ATL) {atl} [{fatigue_zone}], Form (TSB) {tsb} [{form_zone}]. "
        "Health/restriction state is more important than those training-load metrics. If illness or injury explains reduced training, NEVER call the resulting freshness tapering, peaking, race readiness, or improved form. "
        "Instead prioritize health metrics, athlete-reported status and the active restriction. For HRV, resting HR, Sleep Score and SpO2 use personal Garmin baselines plus recent trend, not population thresholds. "
        "SLEEP RULE: sleep duration is interpreted primarily against THE LAB's adaptive 42-day weekday/weekend habitual sleep opportunity. The fixed Garmin 7h38m value is a visible reference, NOT the daily penalty target. Q1/Q2 sleep quality remains a high-priority recovery signal and can partially offset a modest shortfall versus habitual opportunity; severe or accumulating short sleep still matters.\n\n"
        "DETERMINISTIC ENGINE RULE: TRAINING STATE, PHYSIOLOGICAL STATE, AEROBIC EFFICIENCY/DURABILITY and POWER MODEL entries in DATA are computed by Python. Use them as structured context and explain them when relevant; do not silently relabel a health-driven load drop as tapering, and do not treat CP/W′ field estimates as laboratory measurements.\n\n"
        "EVENT RULE: an upcoming registered race changes the purpose and spacing of sessions as race day approaches. Respect days-to-race and do not schedule gratuitous fatigue close to the event. ATHLETE-PLANNED TRAINING RULE: use active Calendar TRAINING entries to shape the days around them and never silently switch their structured environment. "
        "RESTRICTION RULE: temporary restrictions have exact dates. A 12-day no-intensity block means no intentional intensity on any one of those dates, even when CTL/ATL/TSB would otherwise encourage it.\n\n"
        "WEEK-MEMORY RULE: avoid automatically repeating Threshold/TTE, VO2max, Over-Under or sprint/neuromuscular work within about 72h unless there is a clear coaching reason. "
        "HEAT-RESPONSE RULE: activities whose name contains HEAT are deliberate high thermal-strain sessions. Use PREVIOUS TRAINING BLOCKS to inspect their actual interval power, HR response, zones and decoupling instead of judging them from average watts alone. Use the Python PERSONAL HEAT RESPONSE association to contextualize next-morning HRV, but never claim causation and never dismiss low HRV when resting HR, sleep, subjective status or performance also worsen. "
        "SNAPSHOT QUESTION RULE: if SNAPSHOT ATHLETE QUESTION below is not NONE, answer that question explicitly inside the recommendation field during THIS SAME Snapshot AI call. Do not require the athlete to send it again in AI Coach Chat. Put the direct answer first, then continue with the normal coaching recommendation. If it is NONE, behave exactly as usual. "
        "Do not repeat dashboard numbers or baseline ranges unnecessarily; interpret what matters.\n\n"
        "Writing style: concise, visual and decisive. training_load, season_distribution and fatigue_signals normally 1-2 useful sentences; season_outlook 2-3; recommendation 3-5 when needed. "
        "For each session give a specific prescription and short rationale.\n\n"
        "Return ONLY valid JSON with exactly these keys:\n"
        '- "training_load": string\n'
        '- "season_distribution": string\n'
        '- "season_outlook": string\n'
        '- "fatigue_signals": string\n'
        '- "recommendation": string\n'
        '- "next_sessions": array of exactly 3 objects, SAME ORDER as valid slots. Each object contains "title", "duration", "intensity", "main_set", "why". Python owns the slot/date and will enforce restrictions after your response. Each ordinary workout must fit within 60 minutes.\n\n'
        "VALID NEXT SLOTS:\n{slot_lines}\n\n"
        "SNAPSHOT ATHLETE QUESTION (from today's most recent Daily Note; answer in recommendation if present):\n{snapshot_question}\n\n"
        "DATA:\n{data_text}"
    ).format(
        planning_context=planning_context_text(planning_context),
        clock_context=coach_clock_text(coach_clock), week_context=week_memory_text(week_memory),
        subjective_context=subjective_context_text(feeling_trend), baseline_context=personal_baseline_text(metrics),
        metabolic_context=metabolic_context_text(metabolic_context), athlete_context=ATHLETE_CONTEXT,
        ctl=metrics["ctl"], fitness_zone=metrics["fitness_zone"],
        atl=metrics["atl"], fatigue_zone=metrics["fatigue_zone"], tsb=metrics["tsb"], form_zone=metrics["form_zone"],
        slot_lines=slot_lines, snapshot_question=(snapshot_question or "NONE"), data_text=data_text,
    )
    resp = requests.post(
        "https://api.anthropic.com/v1/messages",
        headers={"x-api-key": ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01", "content-type": "application/json"},
        json={"model": "claude-sonnet-4-6", "max_tokens": 2600, "messages": [{"role": "user", "content": prompt}]}, timeout=60,
    )
    resp.raise_for_status()
    resp_data = resp.json()
    raw_text = "".join(block.get("text", "") for block in resp_data.get("content", [])).strip()
    if raw_text.startswith("```"):
        raw_text = raw_text.strip("`")
        if raw_text.startswith("json"):
            raw_text = raw_text[4:]
    try:
        parsed = json.loads(raw_text)
    except json.JSONDecodeError as exc:
        preview = raw_text[:300].replace("\n", " ")
        raise json.JSONDecodeError(f"{exc.msg} | raw response preview: {preview}", exc.doc, exc.pos)
    parsed["next_sessions"] = normalize_next_sessions(parsed.get("next_sessions"), coach_clock)
    return parsed



def _chat_context_section(label, builder, value):
    if not value:
        return None
    try:
        rendered = builder(value)
        if rendered:
            return f"{label}:\n{rendered}"
    except Exception:
        return None
    return None


def build_ai_coach_chat_context(snapshot):
    """Build a compact, high-signal context from the already-saved Snapshot only.

    No Intervals.icu fetch happens here. Deterministic Python outputs are carried
    forward so the conversational layer explains THE LAB instead of reinventing it.
    """
    snapshot = snapshot or {}
    lines = ["CURRENT THE LAB SNAPSHOT (authoritative for this chat):"]
    lines.append(
        "- CTL {ctl} [{fz}] | ATL {atl} [{az}] | TSB {tsb} [{tz}] | Energy Bank {energy}/100 [{el}] | Race Readiness {race}/100 [{rl}]".format(
            ctl=snapshot.get("ctl", "n/a"), fz=snapshot.get("fitness_zone", "n/a"),
            atl=snapshot.get("atl", "n/a"), az=snapshot.get("fatigue_zone", "n/a"),
            tsb=snapshot.get("tsb", "n/a"), tz=snapshot.get("form_zone", "n/a"),
            energy=snapshot.get("energy_score", "n/a"), el=snapshot.get("energy_label", "n/a"),
            race=snapshot.get("race_readiness_score", "n/a"), rl=snapshot.get("race_readiness_label", "n/a"),
        )
    )
    lines.append(
        "- Latest HRV {hrv} | Resting HR {rhr} | Avg sleep {sleep} | Sleep quality {sq} | Weight {weight}".format(
            hrv=snapshot.get("latest_hrv", "n/a"), rhr=snapshot.get("latest_rhr", "n/a"),
            sleep=snapshot.get("avg_sleep", "n/a"), sq=snapshot.get("sleep_quality", "n/a"),
            weight=snapshot.get("latest_weight", "n/a"),
        )
    )
    if snapshot.get("recommendation"):
        lines.append(f"- COACH SNAPSHOT: {snapshot.get('recommendation')}")

    sessions = snapshot.get("next_sessions") or []
    fuels = snapshot.get("nutrition_plan") or []
    if sessions:
        lines.append("\nUPCOMING SESSIONS + FUEL:")
        for idx, sess in enumerate(sessions[:3]):
            fuel = fuels[idx] if idx < len(fuels) and isinstance(fuels[idx], dict) else {}
            lines.append(
                "- {slot} | {title} | {duration} | {intensity} | Fuel {fueling} | demand {demand} | recovery {recovery}".format(
                    slot=sess.get("slot", f"Session {idx+1}"), title=sess.get("title", "Session"),
                    duration=sess.get("duration", "n/a"), intensity=sess.get("intensity", "n/a"),
                    fueling=fuel.get("intra_cho") or "n/a",
                    demand=fuel.get("session_demand", "n/a"), recovery=fuel.get("recovery_need", "n/a"),
                )
            )
            if sess.get("main_set"):
                lines.append(f"  Main set: {sess.get('main_set')}")
            if sess.get("why"):
                lines.append(f"  Why: {sess.get('why')}")
            if fuel.get("guidance"):
                lines.append(f"  Nutrition: {fuel.get('guidance')}")
            if fuel.get("replenishment_guidance"):
                lines.append(f"  Replenishment: {fuel.get('replenishment_guidance')}")

    sections = [
        _chat_context_section("COACH CLOCK", coach_clock_text, snapshot.get("coach_clock")),
        _chat_context_section("TRAINING STATE", training_state_text, snapshot.get("training_state")),
        _chat_context_section("PHYSIOLOGICAL STATE", physiological_state_text, snapshot.get("physiological_state")),
        _chat_context_section("ADAPTIVE SLEEP", adaptive_sleep_text, snapshot.get("adaptive_sleep")),
        _chat_context_section("AEROBIC EFFICIENCY / DURABILITY", aerobic_efficiency_text, snapshot.get("aerobic_efficiency")),
        _chat_context_section("POWER MODEL", power_model_text, snapshot.get("power_model")),
        _chat_context_section("CURRENT WEEK", week_memory_text, snapshot.get("week_memory")),
        _chat_context_section("PREVIOUS TRAINING BLOCKS", previous_training_blocks_text, snapshot.get("previous_training_blocks")),
        _chat_context_section("PERSONAL HEAT RESPONSE", heat_response_pattern_text, snapshot.get("heat_pattern")),
        _chat_context_section("CALENDAR / RESTRICTIONS", planning_context_text, snapshot.get("planning_context")),
        _chat_context_section("METABOLIC / NUTRITION CONTEXT", metabolic_context_text, snapshot.get("metabolic_context")),
    ]
    lines.extend("\n" + x for x in sections if x)
    if snapshot.get("feeling_trend"):
        try:
            lines.append("\nSUBJECTIVE TREND:\n" + subjective_context_text(snapshot.get("feeling_trend"), logs=[]))
        except Exception:
            pass

    vo2 = snapshot.get("vo2_trend") or {}
    if isinstance(vo2, dict) and vo2:
        lines.append(
            "\nVO2MAX TREND (estimated, not measured): wearable {w}, performance {p}, agreement {a}.".format(
                w=vo2.get("wearable_current", "n/a"), p=vo2.get("performance_current", "n/a"), a=vo2.get("agreement", "n/a")
            )
        )
    return "\n".join(lines)


def _normalize_chat_history(raw_history, max_messages=10):
    clean = []
    if not isinstance(raw_history, list):
        return clean
    for item in raw_history[-max_messages:]:
        if not isinstance(item, dict):
            continue
        role = str(item.get("role") or "").strip().lower()
        text = str(item.get("text") or "").strip()
        if role not in ("user", "assistant") or not text:
            continue
        clean.append({"role": role, "text": text[:2500]})
    return clean


def ask_ai_coach_chat(question, snapshot, history=None, report_meta=None):
    """One explicit AI call against the stored Snapshot; never refresh Intervals.icu."""
    now = get_rome_now()
    notes = load_notes()
    notes_text = "\n".join(
        "- [{category}] {date}: {text}".format(
            category=n.get("category", "GENERAL"), date=n.get("date", ""), text=n.get("text", "")
        ) for n in notes[-50:]
    ) or "(none)"
    snapshot_text = build_ai_coach_chat_context(snapshot)
    history = _normalize_chat_history(history)
    history_text = "\n".join(
        ("ATHLETE" if m["role"] == "user" else "AI COACH") + ": " + m["text"] for m in history
    ) or "(new conversation)"
    report_stamp = (report_meta or {}).get("generated_at_local_display") or "unknown timestamp"

    prompt = (
        "You are AI Coach inside THE LAB, a personal cycling decision dashboard. "
        "Answer the athlete's question using the stored Snapshot below. This is a conversational explanation layer: "
        "do not pretend to refresh Intervals.icu, Garmin, weather, or any external source. The Snapshot was generated at {report_stamp}.\n\n"
        "RULES:\n"
        "- Reply in the same language as the athlete's latest question.\n"
        "- Reason from the Snapshot, recent training blocks, calendar/restrictions, personal patterns and deterministic Nutrition Engine outputs.\n"
        "- Treat Python-derived classifications and guardrails as authoritative. Explain them; do not silently override them.\n"
        "- If the data does not support a claim, say what is missing instead of inventing it.\n"
        "- HEAT/HRV findings are associations, not proof of causation.\n"
        "- You may discuss alternatives, but do not claim that the stored Snapshot or calendar has been modified.\n"
        "- Do not mention the underlying AI provider.\n"
        "- Be concise but substantive: normally 2-6 short paragraphs, with a short list only if it materially improves clarity.\n\n"
        "ATHLETE CONTEXT:\n{athlete_context}\n\n"
        "DURABLE MEMORY:\n{notes_text}\n\n"
        "{snapshot_text}\n\n"
        "CONVERSATION SO FAR:\n{history_text}\n\n"
        "LATEST ATHLETE QUESTION:\n{question}\n"
    ).format(
        report_stamp=report_stamp, athlete_context=ATHLETE_CONTEXT, notes_text=notes_text,
        snapshot_text=snapshot_text, history_text=history_text, question=question,
    )

    resp = requests.post(
        "https://api.anthropic.com/v1/messages",
        headers={
            "x-api-key": ANTHROPIC_API_KEY,
            "anthropic-version": "2023-06-01",
            "content-type": "application/json",
        },
        json={
            "model": "claude-sonnet-4-6",
            "max_tokens": 900,
            "messages": [{"role": "user", "content": prompt}],
        },
        timeout=60,
    )
    resp.raise_for_status()
    payload = resp.json()
    answer = "".join(block.get("text", "") for block in payload.get("content", [])).strip()
    if not answer:
        raise ValueError("AI Coach returned an empty answer")
    return answer


def build_vo2max_trend_preview(today=None):
    today = today or date.today()
    wearable = [
        {"date": (today - timedelta(days=49)).isoformat(), "value": 68.0},
        {"date": (today - timedelta(days=35)).isoformat(), "value": 68.4},
        {"date": (today - timedelta(days=21)).isoformat(), "value": 68.7},
        {"date": (today - timedelta(days=7)).isoformat(), "value": 69.0},
        {"date": today.isoformat(), "value": 69.2},
    ]
    performance = [
        {"date": (today - timedelta(days=49)).isoformat(), "value": 70.7},
        {"date": (today - timedelta(days=42)).isoformat(), "value": 70.8},
        {"date": (today - timedelta(days=35)).isoformat(), "value": 71.0},
        {"date": (today - timedelta(days=28)).isoformat(), "value": 71.0},
        {"date": (today - timedelta(days=21)).isoformat(), "value": 71.4},
        {"date": (today - timedelta(days=14)).isoformat(), "value": 71.4},
        {"date": (today - timedelta(days=7)).isoformat(), "value": 71.8},
        {"date": today.isoformat(), "value": 71.8},
    ]
    # Reuse the chart geometry without making API calls.
    original_w = build_wearable_vo2_series
    original_p = build_performance_vo2_series
    try:
        globals()["build_wearable_vo2_series"] = lambda *_args, **_kwargs: wearable
        globals()["build_performance_vo2_series"] = lambda *_args, **_kwargs: performance
        return build_vo2max_trend([])
    finally:
        globals()["build_wearable_vo2_series"] = original_w
        globals()["build_performance_vo2_series"] = original_p


